.profile-next { max-width: 1080px; margin: 0 auto 30px; padding: 45px; background: #0d0a2c; color: white; border-radius: 20px; display: flex; justify-content: space-between; align-items: center; }
.profile-next h2 { font-size: 25px; line-height: 1.45; margin: 9px 0; }.profile-next p { color: #8b95a1; font-size: 10px; }.profile-next .primary-cta { min-width: 220px; }
.restart-text { margin: 0 auto 50px; border: 0; background: none; color: #5f5c7f; display: flex; align-items: center; gap: 6px; font-size: 9px; cursor: pointer; }
.restart-text svg { width: 14px; }

/* Explore */
.explore-page { min-height: 100vh; background: #f6f5ff; }
.explore-head { max-width: 1160px; margin: auto; padding: 38px 24px 22px; display: flex; justify-content: space-between; gap: 32px; align-items: end; }
