.explore-head-actions { display: flex; align-items: center; gap: 8px; padding-bottom: 3px; }
.mini-profile { height: 180px; padding: 10px 20px; display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); background: white; border-radius: 15px; }
