.mini-profile > div:last-child { display: grid; }
.mini-profile small { color: var(--muted); font-size: 8px; }.mini-profile strong { color: var(--green-dark); font: 800 27px "DM Sans"; }.mini-profile span { color: #5f5c7f; font-size: 8px; margin: 3px 0 12px; }
.mini-profile button { border: 0; background: #eef6ff; color: var(--green-dark); padding: 7px 9px; border-radius: 6px; display: flex; align-items: center; gap: 5px; font-size: 8px; font-weight: 700; cursor: pointer; }.mini-profile button svg { width: 12px; }
.compare-strip { max-width: 1112px; margin: 0 auto 32px; padding: 17px 20px; background: #0d0a2c; color: white; border-radius: 13px; display: grid; grid-template-columns: 1fr 1fr 1fr auto; align-items: center; gap: 10px; }
.compare-strip > div span { display: flex; align-items: center; gap: 5px; color: var(--lime); font-size: 8px; }.compare-strip > div span svg { width: 13px; }.compare-strip h3 { font-size: 12px; margin: 4px 0 0; }
.compare-strip > button { min-height: 55px; padding: 10px 13px; border: 1px solid #ffffff1b; border-radius: 8px; background: #ffffff0b; color: white; display: grid; grid-template-columns: 1fr auto; text-align: left; cursor: pointer; }.compare-strip > button:hover { border-color: var(--lime); }.compare-strip > button small { grid-column: 1/-1; color: #5f5c7f; font-size: 7px; }.compare-strip > button strong { font-size: 9px; }.compare-strip > button svg { width: 13px; }
.compare-strip > em { color: #5f5c7f; font-size: 7px; font-style: normal; writing-mode: vertical-rl; }
.explore-tools { max-width: 1112px; margin: 0 auto 14px; display: flex; justify-content: space-between; align-items: center; }
.capital-tabs { display: flex; gap: 4px; }.capital-tabs button { border: 0; background: none; padding: 8px 12px; border-radius: 7px; color: #5f5c7f; font-size: 9px; font-weight: 700; cursor: pointer; }.capital-tabs button.active { background: var(--ink); color: white; }
.explore-tools label { min-width: 142px; height: 40px; padding: 0 10px; border: 1px solid #cccae3; border-radius: 7px; background: white; display: flex; align-items: center; gap: 5px; }.explore-tools label svg { width: 14px; color: #5f5c7f; margin-left: auto; }.explore-tools select { width: 100%; border: 0; background: transparent; color: #585667; outline: none; appearance: none; }
.opportunity-grid { max-width: 1160px; margin: 0 auto; padding: 0 24px; display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.op-card-wrap { position: relative; }
.opportunity-card { min-height: 310px; padding: 24px; background: white; border: 1px solid #dfdef1; border-radius: 8px; position: relative; overflow: hidden; transition: .2s; }
.opportunity-card:before, .opportunity-card:after { display: none; }
.opportunity-card:hover { transform: translateY(-3px); box-shadow: 0 20px 40px #3272db11; }.opportunity-card.saved { border-color: var(--green); box-shadow: 0 0 0 2px #3272db14; }
.op-card-top { min-height: 24px; display: flex; justify-content: space-between; align-items: center; }.op-card-top > span { color: #585667; font-weight: 700; }.op-card-top > strong { color: var(--green-dark); display: flex; align-items: center; gap: 4px; font-size: 12px; }.op-card-top > strong svg { width: 14px; }
.opportunity-card h3 { overflow-wrap: anywhere; font-size: 21px; line-height: 1.45; margin: 15px 0 8px; letter-spacing: 0; }.op-line { min-height: 0; color: var(--muted); line-height: 1.65; max-width: 460px; }
