.op-actions { position: absolute; left: 24px; right: 24px; bottom: 20px; display: flex; gap: 7px; }.op-actions button { width: 38px; height: 38px; padding: 0; border: 1px solid #dfdef1; border-radius: 7px; background: white; display: flex; align-items: center; justify-content: center; gap: 5px; color: #5f5c7f; font-weight: 700; cursor: pointer; }.op-actions button svg { width: 15px; }.op-actions button.active { border-color: #b0b8c1; color: var(--green-dark); background: #eef6ff; }.op-actions button:last-child { width: auto; padding: 0 15px; margin-left: auto; color: white; border-color: var(--ink); background: var(--ink); }
.more-opportunities { margin: 24px auto 48px; height: 42px; border: 1px solid #cccae3; border-radius: 7px; background: white; padding: 0 16px; display: flex; align-items: center; gap: 7px; font-weight: 700; cursor: pointer; }.more-opportunities svg { width: 14px; }
.explore-disclaimer { max-width: 1112px; margin: 30px auto 60px; padding: 17px; border: 1px solid #dfdef1; border-radius: 10px; display: flex; gap: 10px; color: #5f5c7f; }.explore-disclaimer svg { width: 16px; flex: 0 0 auto; }.explore-disclaimer p { font-size: 8px; line-height: 1.7; margin: 0; }.explore-disclaimer strong { color: #585667; }
.empty-results { max-width: 1112px; margin: 30px auto; padding: 70px; text-align: center; background: white; border: 1px solid var(--line); border-radius: 15px; }.empty-results > svg { color: var(--green); }.empty-results h3 { font-size: 18px; }.empty-results p { color: var(--muted); font-size: 10px; }.empty-results button { border: 0; background: var(--ink); color: white; border-radius: 7px; padding: 9px 13px; font-size: 9px; cursor: pointer; }

/* Detail and deepening */
.detail-backdrop { position: fixed; inset: 0; z-index: 100; padding: 20px; background: #101318b5; backdrop-filter: blur(6px); display: flex; justify-content: flex-end; overflow-y: auto; }
.op-detail { width: min(570px, 100%); min-height: 100%; padding: 45px; background: white; border-radius: 18px; position: relative; box-shadow: 0 30px 70px #0004; }
.detail-close { position: absolute; right: 22px; top: 22px; width: 35px; height: 35px; border: 0; border-radius: 50%; background: #f6f5ff; display: grid; place-items: center; cursor: pointer; }.detail-close svg { width: 17px; }
.detail-sector { color: var(--green-dark); font: 800 9px "DM Sans"; letter-spacing: 1px; }.op-detail > h2, .deepening-modal h2 { font-size: 30px; line-height: 1.4; margin: 12px 0 9px; }.detail-lead { color: var(--muted); font-size: 11px; line-height: 1.75; }
.detail-score { margin: 27px 0; padding: 20px; background: #f6f5ff; border-radius: 12px; display: grid; grid-template-columns: 110px 1fr; gap: 8px 20px; }.detail-score > div { grid-row: 1/5; display: grid; align-content: center; border-right: 1px solid #dfdef1; }.detail-score > div strong { color: var(--green-dark); font: 800 35px "DM Sans"; }.detail-score > div strong small { font-size: 12px; }.detail-score > div span { color: #5f5c7f; font-size: 8px; }
.detail-score > span { display: grid; grid-template-columns: 58px 1fr 25px; gap: 6px; align-items: center; }.detail-score > span small { color: #5f5c7f; font-size: 7px; }.detail-score > span i { height: 4px; background: #dfdef1; border-radius: 3px; overflow: hidden; }.detail-score > span i b { display: block; height: 100%; background: var(--green); }.detail-score > span em { font: 700 8px "DM Sans"; text-align: right; }
.op-detail section { padding: 20px 0; border-top: 1px solid #dfdef1; }.op-detail section h3 { font-size: 12px; margin: 0 0 13px; }.op-detail section > p { display: flex; align-items: flex-start; gap: 7px; color: var(--muted); font-size: 9px; }.op-detail section > p svg { width: 14px; color: var(--green); flex: 0 0 auto; }
.first-test, .risk-box { padding: 17px !important; border: 0 !important; border-radius: 10px; background: #eef6ff; display: flex; gap: 11px; }.first-test > svg, .risk-box > svg { color: var(--green-dark); flex: 0 0 auto; }.first-test div, .risk-box div { display: grid; }.first-test small, .risk-box small { color: #585667; font-size: 7px; }.first-test strong { font-size: 10px; line-height: 1.6; margin-top: 4px; }
.skill-tags { display: flex; flex-wrap: wrap; gap: 6px; }.skill-tags span { padding: 6px 8px; background: #f6f5ff; border-radius: 5px; color: #585667; font-size: 8px; }
.risk-box { background: #fff5e9; }.risk-box > svg { color: #b27b35; }.risk-box p, .risk-box em { color: #766757; font-size: 8px; line-height: 1.6; margin: 4px 0; }.risk-box em { color: #a1876d; font-style: normal; }
.detail-actions { display: flex; gap: 7px; margin-top: 22px; }.detail-actions button { flex: 1; height: 46px; border: 1px solid #dfdef1; border-radius: 9px; background: white; display: flex; align-items: center; justify-content: center; gap: 6px; font-size: 9px; font-weight: 700; cursor: pointer; }.detail-actions button svg { width: 15px; }.detail-actions .save-detail { border-color: var(--ink); background: var(--ink); color: white; }
.deepening-modal { width: min(600px, 100%); height: fit-content; margin: auto; padding: 40px; background: white; border-radius: 18px; position: relative; }.deepening-modal > p { color: var(--muted); font-size: 10px; line-height: 1.7; }.deep-options { display: grid; gap: 8px; margin: 25px 0; }.deep-options button { min-height: 54px; padding: 0 15px; border: 1px solid #dfdef1; background: white; border-radius: 9px; display: flex; align-items: center; justify-content: space-between; font-size: 10px; font-weight: 700; cursor: pointer; }.deep-options button:hover { border-color: var(--green); background: #eef6ff; }.deep-options button svg { width: 15px; }.deepening-modal > small { display: flex; align-items: center; gap: 5px; color: #5f5c7f; font-size: 8px; }.deepening-modal > small svg { width: 13px; }

@media (max-width: 640px) {
