/* Motion feedback */
.new-home, .assessment-page, .profile-page, .explore-page { animation: page-enter .45s cubic-bezier(.2,.8,.2,1) both; }
.new-hero-copy > *, .profile-title > * { animation: rise-in .6s cubic-bezier(.2,.8,.2,1) both; }
.new-hero-copy > *:nth-child(2), .profile-title > *:nth-child(2) { animation-delay: .08s; }
.new-hero-copy > *:nth-child(3), .profile-title > *:nth-child(3) { animation-delay: .16s; }
.new-hero-copy > *:nth-child(4), .profile-title > *:nth-child(4) { animation-delay: .24s; }
.profile-preview { animation: card-arrive .7s .15s cubic-bezier(.2,.8,.2,1) both, gentle-tilt 7s 1s ease-in-out infinite; }
.choice-pair > button { animation: choice-arrive .45s cubic-bezier(.2,.8,.2,1) both; }
.choice-pair > button:nth-child(2) { animation-delay: .08s; }
.choice-pair > button.selected { animation: selected-pop .3s ease both; }
.assessment-progress span, .confidence > i b { position: relative; overflow: hidden; }
.assessment-progress span:after, .confidence > i b:after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, transparent, #ffffffa0, transparent); transform: translateX(-100%); animation: shimmer 1.8s ease-in-out infinite; }
.radar-data { transform-origin: center; animation: radar-breathe 3.5s ease-in-out infinite; }
.opportunity-card:after { content: ""; position: absolute; width: 130px; height: 130px; right: -90px; top: -90px; border-radius: 50%; background: #3272db0d; transition: .35s ease; }
.opportunity-card:hover:after { width: 220px; height: 220px; right: -95px; top: -95px; }
.opportunity-card.saved { animation: saved-pulse .45s ease; }
.detail-backdrop { animation: backdrop-in .25s ease both; }
.op-detail, .deepening-modal { animation: panel-in .35s cubic-bezier(.2,.8,.2,1) both; }
.source-list > a, .journey-grid article, .research-grid article, .op-card-wrap {
  animation: scroll-rise linear both;
  animation-timeline: view();
  animation-range: entry 5% cover 25%;
}
@keyframes page-enter { from { opacity: 0; } to { opacity: 1; } }
@keyframes rise-in { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }
@keyframes card-arrive { from { opacity: 0; transform: translateY(25px) rotate(6deg) scale(.96); } to { opacity: 1; transform: rotate(2deg); } }
@keyframes gentle-tilt { 0%,100% { transform: rotate(2deg) translateY(0); } 50% { transform: rotate(-1deg) translateY(-7px); } }
@keyframes choice-arrive { from { opacity: 0; transform: translateY(15px) scale(.98); } to { opacity: 1; transform: none; } }
@keyframes selected-pop { 50% { transform: translateY(-5px) scale(1.015); } }
@keyframes shimmer { 55%,100% { transform: translateX(120%); } }
@keyframes radar-breathe { 0%,100% { transform: scale(.98); opacity: .88; } 50% { transform: scale(1.02); opacity: 1; } }
@keyframes saved-pulse { 50% { box-shadow: 0 0 0 7px #3272db20; } }
@keyframes backdrop-in { from { opacity: 0; } }
@keyframes panel-in { from { opacity: 0; transform: translateX(35px) scale(.98); } }
@keyframes scroll-rise { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: none; } }

