/* Opportunity conversion, checkout, and 21-day workspace */
.detail-actions-stacked { display: grid; grid-template-columns: 1fr 1fr; }
.detail-actions-stacked .start-opportunity { grid-column: 1/-1; height: 54px; color: white; background: var(--green); border-color: var(--green); font-size: 14px; }
.detail-actions-stacked .start-opportunity svg { color: white; }
.detail-actions-stacked .start-opportunity:disabled { cursor: wait; opacity: .72; }
.op-start-error { grid-column: 1/-1; margin: 0; color: #b42318; font-size: 12px; line-height: 1.5; text-align: center; }
.checkout-page { min-height: 100vh; background: #f6f5ff; animation: page-enter .4s ease both; }
.checkout-page .site-header { max-width: none; padding-left: max(24px, calc((100vw - 1180px) / 2)); padding-right: max(24px, calc((100vw - 1180px) / 2)); background: white; border-bottom: 1px solid #dfdef1; }
.checkout-shell { max-width: 1080px; margin: auto; padding: 35px 24px 80px; }
.checkout-heading { margin: 45px 0 36px; }
.checkout-heading h1 { font-size: 38px; line-height: 1.4; letter-spacing: -2px; margin: 9px 0; }
.checkout-heading p { color: var(--muted); font-size: 14px; }
.checkout-layout { display: grid; grid-template-columns: 1.25fr .75fr; gap: 18px; align-items: start; }
.checkout-form { display: grid; gap: 14px; }
.checkout-form > section, .agreement { padding: 26px; border: 1px solid #dfdef1; border-radius: 15px; background: white; }
.checkout-section-title { display: flex; align-items: flex-start; gap: 12px; }
.checkout-section-title > span { width: 29px; height: 29px; display: grid; place-items: center; flex: 0 0 auto; border-radius: 50%; background: #efeefb; color: var(--green-dark); font: 800 10px "DM Sans"; }
.checkout-section-title h2 { font-size: 17px; margin: 2px 0 4px; }
.checkout-section-title p { color: #5f5c7f; font-size: 12px; margin: 0; }
.chosen-opportunity { margin-top: 20px; padding: 20px; border-radius: 11px; background: #f6f5ff; }
.chosen-opportunity > span { color: var(--green-dark); font-size: 11px; font-weight: 800; }
.chosen-opportunity h3 { overflow-wrap: anywhere; font-size: 20px; margin: 5px 0; }
.chosen-opportunity > p { color: var(--muted); font-size: 13px; line-height: 1.65; }
.chosen-opportunity > div { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 12px; }
.chosen-opportunity em { padding: 6px 8px; border-radius: 5px; background: white; color: #585667; font-size: 10px; font-style: normal; }
.payment-methods { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 20px; }
.payment-methods > button { min-height: 90px; padding: 13px; border: 1px solid #dfdef1; border-radius: 10px; background: white; display: grid; grid-template-columns: 28px 1fr 18px; align-items: center; gap: 8px; text-align: left; cursor: pointer; }
.payment-methods > button.active { border: 2px solid var(--green); background: #f9f9ff; }
.payment-methods > button > svg { width: 21px; color: #585667; }
.payment-methods > button > span:nth-child(2) { display: grid; }
.payment-methods strong { font-size: 12px; }
.payment-methods small { color: #8b95a1; font-size: 9px; }
.payment-methods i { width: 18px; height: 18px; display: grid; place-items: center; border-radius: 50%; background: var(--green); color: white; }
.payment-methods i svg { width: 12px; }
.toss-symbol { color: #2764e7; font: 800 13px "DM Sans"; }
.agreement { display: flex; align-items: center; gap: 11px; cursor: pointer; }
.agreement input { width: 20px; height: 20px; accent-color: var(--green); }
.agreement > span { display: grid; flex: 1; }
.agreement strong { font-size: 13px; }
.agreement small { color: #5f5c7f; font-size: 10px; margin-top: 3px; }
.agreement > svg { width: 15px; color: #8b95a1; }
.checkout-security { display: flex; gap: 8px; align-items: flex-start; color: #5f5c7f; padding: 0 8px; }
.checkout-security svg { width: 15px; flex: 0 0 auto; }
.checkout-security p { font-size: 10px; line-height: 1.6; margin: 0; }
.order-summary { padding: 29px; border-radius: 17px; background: #0d0a2c; color: white; position: sticky; top: 20px; box-shadow: 0 22px 50px #0d0a2c24; }
.package-label { color: var(--lime); font: 800 9px "DM Sans"; letter-spacing: 1px; }
.order-summary h2 { font-size: 22px; margin: 8px 0 22px; }
.package-includes { display: grid; gap: 11px; padding-bottom: 22px; border-bottom: 1px solid #ffffff16; }
.package-includes span { display: flex; align-items: center; gap: 7px; color: #b0b8c1; font-size: 11px; }
.package-includes svg { width: 15px; color: #b3a8ff; }
.checkout-sample-button { width: 100%; min-height: 54px; margin: 17px 0 4px; padding: 8px 12px; border: 1px solid #5f5c7f; border-radius: 7px; background: #0d0a2c; color: #fff; display: grid; grid-template-columns: 20px minmax(0, 1fr) 16px; align-items: center; gap: 9px; text-align: left; cursor: pointer; }
.checkout-sample-button > svg { width: 18px; color: #b3a8ff; }
.checkout-sample-button > svg:last-child { width: 14px; color: #cccae3; }
.checkout-sample-button span { min-width: 0; display: grid; gap: 2px; }
.checkout-sample-button small { color: #8b95a1; font-size: 8px; }
.checkout-sample-button strong { font-size: 11px; }
.price-line { display: flex; justify-content: space-between; color: #8b95a1; font-size: 11px; padding-top: 14px; }
.price-line strong { color: #b0b8c1; font-weight: 600; }
.total-line { margin-top: 17px; padding-top: 18px; border-top: 1px solid #ffffff16; display: flex; justify-content: space-between; align-items: end; }
.total-line span { font-size: 12px; }
.total-line strong { font: 800 27px "DM Sans"; color: var(--lime); }
.total-line small { font-size: 12px; }
.pay-button { width: 100%; height: 54px; margin-top: 20px; border: 0; border-radius: 9px; background: var(--lime); display: flex; align-items: center; justify-content: center; gap: 7px; font-size: 13px; font-weight: 800; cursor: pointer; }
.pay-button:disabled { opacity: .35; cursor: not-allowed; }
.pay-button svg { width: 16px; }
.order-summary > p { display: flex; align-items: center; justify-content: center; gap: 5px; color: #5f5c7f; font-size: 9px; }
.order-summary > p svg { width: 13px; }
.pay-spinner { width: 16px; height: 16px; border: 2px solid #0d0a2c36; border-top-color: #0d0a2c; border-radius: 50%; animation: spin-once .8s linear infinite; }

.project-page { min-height: 100vh; display: grid; grid-template-columns: 245px 1fr; background: #f6f5ff; }
.project-sidebar { height: 100vh; padding: 25px 20px; background: #0d0a2c; color: white; position: sticky; top: 0; display: flex; flex-direction: column; }
.project-sidebar .brand { color: white; }
.payment-complete { margin: 32px 0 21px; padding: 13px; border: 1px solid #ffffff12; border-radius: 10px; background: #ffffff09; display: flex; gap: 8px; align-items: center; }
.payment-complete > svg { width: 20px; color: var(--lime); }
.payment-complete span { display: grid; }
.payment-complete small { color: #5f5c7f; font-size: 8px; }
.payment-complete strong { font-size: 10px; }
.project-sidebar nav { display: grid; gap: 4px; }
.project-sidebar nav button { min-height: 54px; padding: 8px 10px; border: 0; border-radius: 8px; background: none; color: #5f5c7f; display: flex; align-items: center; gap: 10px; text-align: left; cursor: not-allowed; }
.project-sidebar nav button.active { background: #ffffff10; color: white; cursor: pointer; }
.project-sidebar nav button.done { color: #8b95a1; cursor: pointer; }
.project-sidebar nav button > span { width: 25px; height: 25px; display: grid; place-items: center; flex: 0 0 auto; border: 1px solid #333d4b; border-radius: 50%; font-size: 8px; }
.project-sidebar nav button.done > span { color: #0d0a2c; background: var(--lime); border-color: var(--lime); }
.project-sidebar nav button > span svg { width: 12px; }
.project-sidebar nav button div { display: grid; }
.project-sidebar nav button strong { font-size: 10px; }
.project-sidebar nav button small { color: #585667; font-size: 8px; }
.automation-card { margin-top: auto; padding-top: 18px; border-top: 1px solid #ffffff12; display: grid; grid-template-columns: 33px 1fr 20px; gap: 9px; align-items: center; }
.automation-card > span { width: 33px; height: 33px; display: grid; place-items: center; background: #efeefb; color: #3272db; border-radius: 50%; font-size: 10px; }
.automation-card > span svg { width: 16px; }
.automation-card > div { display: grid; }
.automation-card small { color: #585667; font-size: 7px; }
.automation-card strong { font-size: 9px; }
.automation-card p { color: #585667; font-size: 7px; margin: 2px 0 0; }
.automation-card > svg { width: 17px; color: #5f5c7f; }
.project-workspace { min-width: 0; }
.project-topbar { height: 72px; padding: 0 38px; border-bottom: 1px solid #dfdef1; background: white; display: flex; align-items: center; justify-content: space-between; }
.project-topbar > div { min-width: 0; display: grid; }
.project-topbar span { color: #5f5c7f; font-size: 8px; }
.project-topbar strong { max-width: min(680px, 65vw); overflow-wrap: anywhere; font-size: 11px; line-height: 1.45; }
.project-topbar button { border: 0; background: none; color: #5f5c7f; font-size: 10px; cursor: pointer; }
.project-overview { margin: 28px 38px 15px; padding: 30px 35px; border-radius: 16px; background: linear-gradient(125deg, #0d0a2c, #3272db); color: white; display: flex; align-items: center; justify-content: space-between; position: relative; overflow: hidden; }
.project-overview:after { content: ""; position: absolute; width: 280px; height: 280px; right: -80px; top: -100px; border: 50px solid #ffffff09; border-radius: 50%; }
.project-status { padding: 6px 8px; border-radius: 14px; background: #ffffff15; color: #d8d4fb; font-size: 8px; font-weight: 700; }
.project-overview p { color: #8b95a1; font-size: 8px; margin: 19px 0 4px; }
.project-overview h1 { max-width: 650px; overflow-wrap: anywhere; font-size: 23px; line-height: 1.35; margin: 0; }
.project-overview > div:first-child > div { display: flex; gap: 15px; margin-top: 16px; }
.project-overview > div:first-child > div span { display: flex; align-items: center; gap: 5px; color: #b0b8c1; font-size: 8px; }
.project-overview > div:first-child > div svg { width: 14px; }
.project-progress { width: 130px; z-index: 1; display: grid; grid-template-columns: 1fr auto; align-items: end; }
.project-progress strong { font: 800 38px "DM Sans"; }
.project-progress strong small { font-size: 13px; }
.project-progress > span { color: #8b95a1; font-size: 8px; }
.project-progress i { grid-column: 1/-1; height: 5px; margin-top: 8px; background: #ffffff20; border-radius: 4px; overflow: hidden; }
.project-progress i b { display: block; height: 100%; background: var(--lime); border-radius: 4px; transition: width .4s; }
.stage-layout { padding: 0 38px 60px; display: grid; grid-template-columns: 1.35fr .65fr; gap: 15px; }
.current-stage-card, .project-side-panel > section { padding: 27px; border: 1px solid #dfdef1; border-radius: 15px; background: white; }
.stage-heading { display: flex; gap: 17px; }
.stage-heading > span { color: #cccae3; font: 800 38px "DM Sans"; }
.stage-heading small { color: var(--green-dark); font-size: 9px; font-weight: 800; }
.stage-heading h2 { overflow-wrap: anywhere; font-size: 22px; line-height: 1.35; margin: 5px 0; }
.stage-heading p { color: var(--muted); font-size: 11px; line-height: 1.7; margin: 0; }
.stage-task-list { margin-top: 25px; }
.stage-task-list > div { display: flex; justify-content: space-between; margin-bottom: 8px; }
.stage-task-list > div strong { font-size: 11px; }
.stage-task-list > div span { color: #5f5c7f; font-size: 8px; }
.stage-task-list > button { width: 100%; min-height: 54px; padding: 9px 12px; border: 0; border-top: 1px solid #dfdef1; background: white; display: grid; grid-template-columns: 23px 1fr 18px; align-items: center; gap: 10px; text-align: left; cursor: pointer; }
.stage-task-list > button > span { width: 21px; height: 21px; display: grid; place-items: center; border: 1px solid #b0b8c1; border-radius: 50%; }
.stage-task-list > button > span svg { width: 12px; }
.stage-task-list > button strong { font-size: 10px; }
.stage-task-list > button > svg { width: 14px; color: #8b95a1; }
.stage-task-list > button.checked > span { color: white; background: var(--green); border-color: var(--green); }
.stage-task-list > button.checked strong { color: #5f5c7f; text-decoration: line-through; }
.stage-output { margin: 18px 0; padding: 15px; border-radius: 9px; background: #eef6ff; color: #333d4b; display: flex; align-items: center; gap: 10px; }
.stage-output > svg { color: var(--green); }
.stage-output > div { font-size: 9px; }
.stage-output small { display: block; color: #5f5c7f; font-size: 7px; }
.complete-stage { width: 100%; height: 49px; border: 0; border-radius: 8px; background: var(--green); color: white; display: flex; align-items: center; justify-content: center; gap: 7px; font-size: 10px; font-weight: 800; cursor: pointer; }
.complete-stage:disabled { background: #dfdef1; color: #8b95a1; cursor: not-allowed; }
.complete-stage svg { width: 15px; }
.project-side-panel { display: grid; gap: 12px; align-content: start; }
.project-side-panel > section { padding: 20px; }
.panel-title { display: flex; align-items: center; gap: 8px; }
.panel-title > svg { width: 18px; color: var(--green); }
.panel-title > div { display: grid; }
.panel-title strong { font-size: 10px; }
.panel-title small { color: #5f5c7f; font-size: 7px; }
.generation-status { margin-top: 15px; padding: 12px; border-radius: 8px; background: #f6f5ff; display: grid; grid-template-columns: 7px 1fr auto; align-items: center; gap: 8px; }
.generation-status > span { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 4px #3272db18; animation: radar-breathe 1.5s infinite; }
.generation-status p { display: grid; margin: 0; }
.generation-status strong { font-size: 8px; }
.generation-status small { color: #8b95a1; font-size: 7px; }
.generation-status em { color: var(--green-dark); font-size: 7px; font-style: normal; }
.empty-doc { color: #8b95a1; font-size: 8px; text-align: center; padding: 20px 0 5px; }
.project-doc { width: 100%; margin-top: 10px; padding: 9px 0; border: 0; border-top: 1px solid #dfdef1; background: white; display: grid; grid-template-columns: 30px 1fr 15px; gap: 8px; align-items: center; text-align: left; cursor: pointer; }
.project-doc > span { width: 30px; height: 30px; display: grid; place-items: center; background: #f6f5ff; border-radius: 7px; color: #585667; }
.project-doc > span svg, .project-doc > svg { width: 14px; }
.project-doc div { display: grid; }
.project-doc strong { font-size: 8px; }
.project-doc small { color: #8b95a1; font-size: 7px; }
.help-panel { background: #fff7e9 !important; border-color: #f0e3cc !important; display: flex; align-items: flex-start; gap: 9px; }
.help-panel > svg { color: #b88139; flex: 0 0 auto; }
.help-panel strong { font-size: 10px; }
.help-panel p { color: #8b765a; font-size: 8px; line-height: 1.6; }
.help-panel button { border: 0; background: none; color: #96692f; padding: 0; font-size: 8px; font-weight: 800; cursor: pointer; }

@media (max-width: 640px) {
  .checkout-layout { grid-template-columns: 1fr; }.order-summary { position: static; }
  .project-page { grid-template-columns: 1fr; }.project-sidebar { height: auto; position: static; padding: 18px; }.project-sidebar nav { grid-template-columns: repeat(6, 1fr); overflow-x: auto; }.project-sidebar nav button { min-width: 105px; }.payment-complete, .automation-card { display: none; }
  .stage-layout { grid-template-columns: 1fr; }
}
@media (max-width: 620px) {
  .checkout-shell { padding-left: 18px; padding-right: 18px; }.checkout-heading h1 { font-size: 29px; }.payment-methods { grid-template-columns: 1fr; }.payment-methods > button { min-height: 65px; }.agreement { align-items: flex-start; }
  .project-sidebar nav { grid-template-columns: repeat(6, 95px); }.project-sidebar .brand { margin-bottom: 14px; }
  .project-topbar { padding: 0 18px; }.project-overview { margin: 18px; padding: 25px 22px; display: block; }.project-overview h1 { max-width: 100%; font-size: 19px; }.project-progress { margin-top: 20px; }
  .stage-layout { padding: 0 18px 50px; }.current-stage-card { padding: 22px 18px; }.stage-heading > span { display: none; }.stage-heading h2 { font-size: 20px; }
}

.project-page p, .project-page button, .project-page strong { font-size: max(12px, 1em); }
.project-page small, .project-page .project-status, .project-page .project-topbar span,
.project-page .stage-task-list > div span, .project-page .stage-output small,
.project-page .generation-status em { font-size: 11px; }
.project-sidebar nav button strong, .payment-complete strong, .automation-card strong,
.project-topbar strong, .stage-task-list > button strong, .complete-stage,
.panel-title strong, .generation-status strong, .project-doc strong,
.help-panel strong, .help-panel button { font-size: 12px; }
.project-sidebar nav button small, .payment-complete small, .automation-card small,
.automation-card p, .panel-title small, .generation-status small, .project-doc small {
  font-size: 10px;
}
.stage-heading p, .help-panel p, .empty-doc { font-size: 13px; }

/* Final delivery */
.delivery-page { min-height: 100vh; overflow-x: clip; background: #f6f5ff; animation: page-enter .4s ease both; }
.delivery-page .site-header { max-width: none; padding-left: max(24px, calc((100vw - 1180px) / 2)); padding-right: max(24px, calc((100vw - 1180px) / 2)); background: white; border-bottom: 1px solid #dfdef1; }
.sample-preview-bar { position: sticky; top: 0; z-index: 70; min-height: 74px; padding: 13px max(24px, calc((100vw - 1140px) / 2)); border-bottom: 1px solid #cccae3; background: #eef6ff; display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.sample-preview-bar > div { display: grid; gap: 3px; }
.sample-preview-bar span { color: #3272db; display: flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 800; }
.sample-preview-bar span svg { width: 16px; }
.sample-preview-bar strong { color: #0d0a2c; font-size: 14px; }
.sample-preview-bar > button { min-height: 42px; padding: 0 16px; border: 0; border-radius: 7px; background: #0d0a2c; color: white; display: flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 800; cursor: pointer; white-space: nowrap; }
.sample-preview-bar > button svg { width: 15px; }
.delivery-content { max-width: 1180px; margin: auto; padding: 28px 24px 70px; display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; align-items: start; }
.delivery-main { min-width: 0; }
.final-report-viewer { min-height: 620px; margin-bottom: 34px; border: 1px solid #cccae3; border-radius: 8px; background: white; box-shadow: 0 18px 48px #0d0a2c12; overflow: hidden; display: grid; grid-template-columns: 182px minmax(0, 1fr); grid-template-rows: 52px minmax(0, 1fr); grid-template-areas: "chrome chrome" "sidebar main"; }
.final-report-chrome { grid-area: chrome; min-width: 0; padding: 0 15px; border-bottom: 1px solid #dfdef1; background: #f9f9ff; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; }
.final-report-chrome > div { display: flex; gap: 4px; }
.final-report-chrome > div i { width: 8px; height: 8px; border-radius: 50%; background: #b0b8c1; }
.final-report-chrome > div i:first-child { background: #ef8d70; }
.final-report-chrome > div i:last-child { background: #5f5c7f; }
.final-report-chrome > span { min-width: 0; overflow: hidden; color: #2c3440; display: flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }
.final-report-chrome > span svg { width: 15px; flex: 0 0 auto; color: #3272db; }
.final-report-chrome > em, .final-report-main > header > em { padding: 6px 8px; border: 1px solid #b0b8c1; border-radius: 5px; color: #3272db; display: flex; align-items: center; gap: 6px; font-size: 9px; font-style: normal; font-weight: 800; white-space: nowrap; }
.final-report-chrome > em i, .final-report-main > header > em i { width: 6px; height: 6px; border-radius: 50%; background: #3272db; box-shadow: 0 0 0 4px #3272db18; }
.mobile-report-menu-trigger, .mobile-report-sidebar-close, .mobile-report-backdrop,
.mobile-report-progress, .mobile-report-actions { display: none; }
.final-report-sidebar { grid-area: sidebar; min-width: 0; padding: 22px 13px 16px; border-right: 1px solid #dfdef1; background: #f6f5ff; display: flex; flex-direction: column; }
.final-report-sidebar > header { min-width: 0; margin: 0 7px 17px; display: grid; gap: 3px; }
.final-report-sidebar > header > span { min-width: 0; display: grid; gap: 3px; }
.final-report-sidebar > header small { color: #5f5c7f; font-size: 9px; font-weight: 800; }
.final-report-sidebar > header strong { overflow: hidden; color: #0d0a2c; font-size: 13px; text-overflow: ellipsis; white-space: nowrap; }
.final-report-sidebar > nav { display: grid; gap: 5px; }
.final-report-sidebar > nav button { width: 100%; min-height: 52px; padding: 6px 9px; border: 0; border-radius: 5px; background: transparent; color: #5f5c7f; display: grid; grid-template-columns: 17px minmax(0, 1fr) 14px; gap: 7px; align-items: center; text-align: left; font-size: 11px; font-weight: 700; cursor: pointer; }
.final-report-sidebar > nav button:hover { background: #f6f5ff; color: #333d4b; }
.final-report-sidebar > nav button.active { background: #efeefb; color: #3272db; font-weight: 800; box-shadow: inset 3px 0 #3272db; }
.final-report-sidebar > nav button svg { width: 15px; }
.final-report-sidebar > nav button svg:last-child { width: 12px; }
.final-report-sidebar > nav button span { min-width: 0; display: grid; gap: 1px; overflow: hidden; }
.final-report-sidebar > nav button span b { overflow: hidden; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.final-report-sidebar > nav button span small { color: #8b95a1; font-size: 8px; font-weight: 700; white-space: nowrap; }
.final-report-sidebar > nav button.active span small { color: #585667; }
.final-report-sidebar-status { margin-top: auto; padding: 13px 9px 4px; border-top: 1px solid #cccae3; display: grid; gap: 4px; }
.final-report-sidebar-status span { color: #585667; display: flex; align-items: center; gap: 5px; font-size: 9px; font-weight: 800; }
.final-report-sidebar-status span svg { width: 13px; color: #3272db; }
.final-report-sidebar-status strong { color: #0d0a2c; font-size: 18px; }
