.refinement-evidence-summary small { color: #5f5c7f; font-size: 9px; }
.refinement-evidence-summary > button, .refinement-ai-review > header > button { min-height: 44px; padding: 0 14px; border: 0; border-radius: 6px; background: #3272db; color: #fff; display: flex; align-items: center; justify-content: center; gap: 7px; cursor: pointer; font-size: 11px; font-weight: 800; }
.refinement-evidence-summary > button:disabled, .refinement-ai-review > header > button:disabled { opacity: .55; cursor: default; }
