.refinement-evidence-list > article:first-child { border-top: 0; }
.refinement-evidence-list > article > span { color: #3272db; }
.refinement-evidence-list > article > span svg { width: 18px; }
.refinement-evidence-list > article > div { min-width: 0; display: grid; gap: 2px; }
.refinement-evidence-list strong { overflow-wrap: anywhere; color: #333d4b; font-size: 11px; }
