.refinement-evidence-list small { color: #5f5c7f; font-size: 9px; }
.refinement-evidence-list a { padding: 6px 8px; border: 1px solid #cccae3; border-radius: 5px; color: #3272db; font-size: 9px; font-weight: 800; text-decoration: none; }
.refinement-empty-evidence { min-height: 150px; padding: 24px; color: #5f5c7f; display: grid; place-items: center; align-content: center; gap: 5px; text-align: center; }
