.refinement-empty-evidence strong { font-size: 12px; }
.refinement-empty-evidence p { max-width: 500px; line-height: 1.6; }
.refinement-note { margin-top: 18px; }
.refinement-note span em { color: #5f5c7f; font-size: 9px; font-style: normal; }
.refinement-review-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; align-items: start; }
.refinement-diff-panel, .refinement-ai-review, .refinement-history { border: 1px solid #cccae3; border-radius: 7px; background: #fff; overflow: hidden; }
.refinement-diff-panel > header, .refinement-ai-review > header { min-height: 68px; padding: 12px 14px; border-bottom: 1px solid #dfdef1; background: #f9f9ff; display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.refinement-diff-panel > header > div, .refinement-ai-review > header > div { min-width: 0; display: flex; align-items: center; gap: 9px; }
.refinement-diff-panel > header svg, .refinement-ai-review > header > div > svg { width: 19px; color: #3272db; flex: 0 0 auto; }
.refinement-diff-panel > header span, .refinement-ai-review > header span { min-width: 0; display: grid; gap: 2px; }
.refinement-diff-panel > header strong, .refinement-ai-review > header strong { color: #333d4b; font-size: 11px; }
.refinement-diff-panel > header small, .refinement-ai-review > header small { color: #5f5c7f; font-size: 8px; line-height: 1.45; }
.refinement-diff-panel > div > article { padding: 12px 14px; border-top: 1px solid #dfdef1; display: grid; gap: 7px; }
.refinement-diff-panel > div > article:first-child { border-top: 0; }
.refinement-diff-panel > div > article > strong { color: #585667; font-size: 9px; }
.refinement-diff-panel > div > article p { margin: 0; min-width: 0; display: grid; grid-template-columns: minmax(0, 1fr) 14px minmax(0, 1fr); align-items: center; gap: 5px; }
.refinement-diff-panel del, .refinement-diff-panel ins { overflow-wrap: anywhere; font-size: 10px; line-height: 1.5; text-decoration: none; }
.refinement-diff-panel del { color: #5f5c7f; }
.refinement-diff-panel ins { color: #3272db; font-weight: 800; }
.refinement-diff-panel p svg { width: 13px; color: #8b95a1; }
.refinement-no-change { min-height: 180px; padding: 20px; color: #5f5c7f; display: grid; place-items: center; align-content: center; gap: 5px; text-align: center; }
.refinement-no-change svg { width: 24px; color: #3272db; }
.refinement-no-change strong { font-size: 11px; }
.refinement-no-change p { margin: 0; font-size: 9px; }
.refinement-review-result { padding: 13px; display: grid; gap: 9px; }
.refinement-review-result > p { margin: 0; color: #585667; font-size: 10px; line-height: 1.6; }
.refinement-review-result > .warning { padding: 9px; border-radius: 5px; background: #fff7eb; color: #755d35; display: flex; align-items: flex-start; gap: 7px; font-size: 9px; line-height: 1.5; }
.refinement-review-result > .warning svg { width: 14px; flex: 0 0 auto; }
.refinement-review-result > article { padding: 11px; border: 1px solid #cccae3; border-radius: 6px; background: #f9f9ff; display: grid; gap: 4px; }
.refinement-review-result > article small { color: #3272db; font-size: 8px; font-weight: 800; }
.refinement-review-result > article strong { color: #2c3440; font-size: 10px; line-height: 1.5; overflow-wrap: anywhere; }
.refinement-review-result > article p { margin: 0; color: #5f5c7f; font-size: 9px; line-height: 1.5; }
.refinement-review-result > article button { justify-self: end; min-height: 32px; padding: 0 9px; border: 1px solid #3272db; border-radius: 5px; background: #fff; color: #3272db; display: flex; align-items: center; gap: 5px; cursor: pointer; font-size: 9px; font-weight: 800; }
.refinement-review-result > article button svg { width: 13px; }
.refinement-history { margin-top: 15px; }
.refinement-history > header { min-height: 58px; padding: 10px 14px; border-bottom: 1px solid #dfdef1; background: #f9f9ff; display: flex; align-items: center; gap: 9px; }
.refinement-history > header > svg { width: 19px; color: #3272db; }
.refinement-history > header > div { display: grid; gap: 2px; }
.refinement-history > header strong { color: #333d4b; font-size: 11px; }
.refinement-history > header small { color: #5f5c7f; font-size: 8px; }
.refinement-history > div { display: grid; grid-template-columns: repeat(2, 1fr); }
.refinement-history > div > button { min-width: 0; min-height: 62px; padding: 9px 12px; border: 0; border-top: 1px solid #dfdef1; border-left: 1px solid #dfdef1; background: #fff; display: grid; grid-template-columns: minmax(0, 1fr) auto 14px; align-items: center; gap: 7px; text-align: left; cursor: pointer; }
.refinement-history > div > button.active { background: #eef6ff; box-shadow: inset 3px 0 #3272db; }
.refinement-history > div > button span { min-width: 0; display: grid; gap: 2px; }
.refinement-history > div > button strong { overflow: hidden; color: #333d4b; font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.refinement-history > div > button small { color: #5f5c7f; font-size: 8px; }
.refinement-history > div > button em { padding: 4px 6px; border-radius: 4px; background: #f6f5ff; color: #585667; font-size: 8px; font-style: normal; font-weight: 800; white-space: nowrap; }
.refinement-history > div > button em.processing { background: #fff3da; color: #85692f; }
.refinement-history > div > button em.failed { background: #fdeceb; color: #a44c47; }
.refinement-history > div > button svg { width: 13px; color: #5f5c7f; }
.refinement-studio-footer { min-height: 76px; padding: 12px 22px; border-top: 1px solid #dfdef1; background: #fff; display: grid; grid-template-columns: 150px minmax(80px, 1fr) 190px; align-items: center; gap: 18px; }
.refinement-studio-footer > span { height: 4px; border-radius: 4px; background: #dfdef1; overflow: hidden; }
.refinement-studio-footer > span i { display: block; height: 100%; border-radius: inherit; background: #3272db; transition: width .2s ease; }
.refinement-studio-footer > button { min-height: 46px; padding: 0 14px; border-radius: 6px; display: flex; align-items: center; justify-content: center; gap: 7px; cursor: pointer; font-size: 11px; font-weight: 800; }
.refinement-studio-footer > button svg { width: 16px; }
.refinement-studio-footer > button.back { border: 1px solid #cccae3; background: #fff; color: #585667; }
.refinement-studio-footer > button.next, .refinement-studio-footer > button.apply { border: 0; background: #3272db; color: #fff; }
.refinement-studio-footer > button:disabled { opacity: .38; cursor: default; }

@keyframes refinement-fade { from { opacity: 0; } }
@keyframes refinement-rise { from { opacity: 0; transform: translateY(12px); } }

@media (max-width: 640px) {
  .refinement-launch-card { margin: 12px 12px 0; padding: 12px; align-items: stretch; flex-direction: column; gap: 11px; }
  .refinement-launch-card > div { grid-template-columns: 38px minmax(0, 1fr); }
  .refinement-launch-card > div > span { width: 38px; height: 38px; }
  .refinement-launch-card p { display: none; }
  .refinement-launch-card > button { width: 100%; min-height: 46px; }
  .refinement-studio-overlay { padding: 0; background: #fff; backdrop-filter: none; }
  .refinement-studio { width: 100%; height: 100dvh; border: 0; border-radius: 0; box-shadow: none; }
  .refinement-studio-header { min-height: 74px; padding: 11px 14px; }
  .refinement-studio-header h2 { font-size: 19px; }
  .refinement-studio-header p { display: none; }
  .refinement-studio-header > button { width: 40px; height: 40px; }
  .refinement-progress { min-height: 43px; padding: 0 14px; gap: 6px; }
  .refinement-progress button { height: 100%; padding: 0; border-bottom-width: 3px; }
  .refinement-progress button i { display: none; }
  .refinement-progress button span { display: none; }
  .refinement-progress button::after { content: ""; width: 100%; height: 4px; border-radius: 5px; background: #dfdef1; }
  .refinement-progress button.done::after, .refinement-progress button.active::after { background: #3272db; }
  .refinement-step { padding: 23px 17px 30px; }
  .refinement-step > header { margin-bottom: 20px; }
  .refinement-step > header h3 { font-size: 20px; }
  .refinement-step > header p { font-size: 11px; }
  .refinement-fields, .refinement-money-grid, .refinement-review-layout { grid-template-columns: 1fr; gap: 15px; }
  .refinement-fields label.wide { grid-column: 1; }
  .refinement-fields input { min-height: 50px; font-size: 16px; }
  .refinement-fields textarea, .refinement-note textarea { font-size: 16px; }
  .refinement-money-field input { font-size: 18px; }
  .refinement-finance-check { grid-template-columns: 1fr; }
  .refinement-finance-check span { padding: 12px 14px; border-left: 0; border-top: 1px solid #dfdef1; grid-template-columns: 1fr auto; align-items: center; }
  .refinement-finance-check span:first-child { border-top: 0; }
  .refinement-finance-check strong { font-size: 14px; text-align: right; }
  .refinement-evidence-summary { min-height: 0; grid-template-columns: 1fr 1fr; }
  .refinement-evidence-summary > button { grid-column: 1 / -1; }
  .refinement-evidence-list > article { grid-template-columns: 22px minmax(0, 1fr); }
  .refinement-evidence-list > article > a { grid-column: 2; justify-self: start; }
  .refinement-diff-panel > div > article p { grid-template-columns: 1fr; }
  .refinement-diff-panel p svg { transform: rotate(90deg); justify-self: center; }
  .refinement-history > div { grid-template-columns: 1fr; }
  .refinement-studio-footer { min-height: 78px; padding: 10px 14px max(10px, env(safe-area-inset-bottom)); grid-template-columns: 88px minmax(0, 1fr); gap: 9px; }
  .refinement-studio-footer > span { display: none; }
  .refinement-studio-footer > button { min-height: 50px; font-size: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .refinement-studio-overlay, .refinement-studio { animation: none; }
}

/* Real stage work products */
.work-product { margin: 25px 0 8px; padding: 22px; border: 1px solid #dfdef1; border-radius: 13px; background: #f9f9ff; }
.work-product-head { display: flex; justify-content: space-between; align-items: start; padding-bottom: 16px; border-bottom: 1px solid #dfdef1; }
.work-product-head > div { display: grid; }
.work-product-head span { color: var(--green-dark); font: 800 10px "DM Sans"; letter-spacing: 1px; }
.work-product-head h3 { font-size: 17px; margin: 4px 0 0; }
.work-product-head > button { height: 34px; padding: 0 10px; border: 1px solid #cccae3; border-radius: 7px; background: white; display: flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 700; cursor: pointer; }
.work-product-head > button svg { width: 13px; }
.work-product-head > button:disabled { opacity: .5; cursor: wait; }
.work-product-head > .auto-update-label { padding: 7px 9px; border-radius: 7px; background: #eef6ff; display: flex; align-items: center; gap: 5px; color: #585667; font: 700 10px var(--font-sans); letter-spacing: 0; }
.work-product-head > .auto-update-label svg { width: 13px; }
.brief-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 17px; }
.brief-grid article { min-height: 95px; padding: 14px; border-radius: 9px; background: white; border: 1px solid #dfdef1; display: grid; align-content: start; }
.brief-grid small, .brand-core > small { color: #5f5c7f; font-size: 10px; }
.brief-grid strong { font-size: 12px; line-height: 1.65; margin-top: 6px; }
.automation-insight { margin-top: 12px; padding: 13px; border-radius: 8px; background: #efeefb; display: flex; align-items: flex-start; gap: 8px; color: #585667; }
.automation-insight > svg { width: 17px; color: var(--green); flex: 0 0 auto; }
.automation-insight p { font-size: 11px; line-height: 1.65; margin: 0; }
.automation-insight strong { display: block; color: #333d4b; }
.automation-insight.warning { background: #fff5e7; color: #7b674f; }.automation-insight.warning > svg { color: #bd843a; }.automation-insight.warning strong { color: #815b2f; }
.diagnosis-document { display: grid; margin-top: 8px; }
.diagnosis-document article { padding: 16px 0; border-bottom: 1px solid #dfdef1; display: grid; grid-template-columns: 35px 1fr; gap: 7px; }
.diagnosis-document article > span { color: #8b95a1; font: 800 11px "DM Sans"; }
.diagnosis-document article > div > small { color: var(--green-dark); font-size: 10px; font-weight: 800; }
.diagnosis-document h4 { font-size: 13px; line-height: 1.6; margin: 5px 0; }
.diagnosis-document p { color: #5f5c7f; font-size: 11px; line-height: 1.65; margin: 0; }
.evidence-scores { display: flex; gap: 5px; margin: 7px 0; }
.evidence-scores b { padding: 6px 8px; border-radius: 5px; background: #efeefb; color: #585667; font-size: 10px; }
.interview-script { margin-top: 13px; padding: 15px; border-radius: 9px; background: #0d0a2c; color: white; }
.interview-script > strong { font-size: 11px; color: var(--lime); }
.interview-script ol { padding-left: 20px; margin: 9px 0 0; }
.interview-script li { color: #b0b8c1; font-size: 10px; line-height: 1.8; }
.pricing-tiers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; margin-top: 17px; }
.pricing-tiers article { min-height: 185px; padding: 15px; border: 1px solid #dfdef1; border-radius: 9px; background: white; position: relative; }
.pricing-tiers article.recommended { border: 2px solid var(--green); }
.pricing-tiers article > span { position: absolute; right: 9px; top: 9px; padding: 4px 6px; border-radius: 5px; background: var(--green); color: white; font-size: 8px; font-weight: 800; }
.pricing-tiers small { color: #5f5c7f; font: 700 8px "DM Sans"; }
.pricing-tiers article > strong { display: block; font: 800 18px "DM Sans"; margin: 8px 0 17px; }
.pricing-tiers label { display: flex; align-items: center; margin: 8px 0 14px; font-size: 10px; }
.pricing-tiers input { width: 95px; border: 0; border-bottom: 1px solid var(--green); background: transparent; font: 800 17px "DM Sans"; outline: none; }
.pricing-tiers h4 { font-size: 12px; margin: 0 0 5px; }
.pricing-tiers p { color: #5f5c7f; font-size: 9px; line-height: 1.6; }
.economics-grid { display: grid; grid-template-columns: repeat(4, 1fr); margin-top: 10px; padding: 13px; border-radius: 8px; background: #0d0a2c; color: white; }
.economics-grid span { display: grid; padding: 0 10px; border-right: 1px solid #ffffff16; }.economics-grid span:last-child { border: 0; }
.economics-grid small { color: #5f5c7f; font-size: 8px; }.economics-grid strong { color: var(--lime); font: 800 13px "DM Sans"; margin-top: 3px; }
.brand-core { margin-top: 17px; padding: 18px; border-radius: 10px; background: #0d0a2c; color: white; }
