.brand-core > div { display: flex; gap: 5px; }.brand-core > div span { padding: 5px 7px; border-radius: 5px; background: #ffffff10; color: #8b95a1; font: 700 9px var(--font-sans); letter-spacing: 0; }
.brand-candidates { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; margin-top: 10px; }
