.evidence-hero-scene { min-width: 0; }
.hero-report-stage {
  --report-rotate-x: 0deg;
  --report-rotate-y: 0deg;
  --report-rotate-z: 0deg;
  --report-shift-x: 0px;
  --report-shift-y: 0px;
  width: 100%;
  height: 100%;
  position: relative;
  display: grid;
  place-items: center;
  isolation: isolate;
  pointer-events: auto;
}
.hero-report-axis { position: absolute; z-index: 0; background: #585667; opacity: .42; }
.hero-report-axis:after { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 16px #b3a8ff; position: absolute; animation: hero-report-axis-pulse 4s ease-in-out infinite; }
