.hero-report-tilt { width: min(455px, 84%); position: relative; z-index: 2; transform: translate(calc(var(--report-shift-x) * .22), calc(var(--report-shift-y) * .22)) rotate(var(--report-rotate-z)); transition: transform .16s ease-out; }
.hero-report-card { width: 100%; overflow: hidden; border: 1px solid #cccae3; border-radius: 8px; background: #fff; color: #0d0a2c; box-shadow: 0 32px 80px #10131870, 0 0 0 1px #ffffff18; position: relative; animation: hero-report-card-arrive .9s cubic-bezier(.2,.85,.2,1) both; }
