.hero-report-card > header > em i { width: 5px; height: 5px; border-radius: 50%; background: #3272db; box-shadow: 0 0 0 4px #3272db18; animation: hero-report-status 1.8s ease-in-out infinite; }
.hero-report-workspace { min-height: 342px; display: grid; grid-template-columns: 112px minmax(0, 1fr); }
