@keyframes hero-report-bar { 0%, 100% { transform: scaleY(.35); opacity: .45; } 45%, 70% { transform: scaleY(1); opacity: 1; } }
@keyframes hero-report-check { 0%, 15%, 100% { opacity: 0; transform: translateY(4px); } 30%, 82% { opacity: 1; transform: translateY(0); } }
@keyframes hero-report-scan { 0%, 15%, 100% { opacity: 0; transform: translateY(0); } 22% { opacity: .9; } 72% { opacity: .45; transform: translateY(340px); } 78% { opacity: 0; transform: translateY(340px); } }
