.home-research-evidence { padding: 58px 24px 60px; border-bottom: 1px solid #cccae3; background: #fff; }
.home-research-inner { width: min(1200px, 100%); margin: auto; display: grid; grid-template-columns: 330px minmax(0, 1fr); gap: 70px; align-items: start; }
.home-research-inner > header > span { color: #3272db; font-size: 11px; font-weight: 800; }
