.home-research-list { border-top: 1px solid #b0b8c1; border-bottom: 1px solid #b0b8c1; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.home-research-list > a { min-width: 0; min-height: 150px; padding: 22px 18px; border-left: 1px solid #cccae3; color: #0d0a2c; display: grid; grid-template-columns: 25px minmax(0, 1fr) 16px; gap: 9px; align-items: start; transition: background .18s ease; }
.home-research-list > a:first-child { border-left: 0; }
.home-research-list > a:hover { background: #f6f5ff; }
.home-research-list > a > em { color: #8b95a1; font-size: 9px; font-style: normal; font-weight: 800; }
