.landing-photo.size-md img, .landing-photo.size-md .landing-photo-empty { aspect-ratio: 4 / 3; max-width: 100%; }
.landing-photo.size-lg img, .landing-photo.size-lg .landing-photo-empty { aspect-ratio: 3 / 4; max-width: 100%; }

.landing-photo.shape-square img, .landing-photo.shape-square .landing-photo-empty { border-radius: 0; }
.landing-photo.shape-round img, .landing-photo.shape-round .landing-photo-empty { border-radius: 14px; }
.landing-photo.shape-circle img, .landing-photo.shape-circle .landing-photo-empty { border-radius: 50%; aspect-ratio: 1; }

.landing-photo.fit-cover img { object-fit: cover; }
.landing-photo.fit-contain img { object-fit: contain; background: var(--surface-2, #f6f5ff); }

/* 사진을 아직 안 고른 자리 — 빈칸이면 끌어 놓을 자리가 안 보인다 */
