  color: var(--text-3, #8b95a1);
  display: grid;
  place-items: center;
  font-size: 12.5px;
}

.landing-block-photogrid { display: grid; gap: 22px; }
.landing-photogrid-zone { display: grid; gap: 16px; }
.landing-block-photogrid.cols-2 .landing-photogrid-zone { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.landing-block-photogrid.cols-3 .landing-photogrid-zone { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.landing-block-photogrid.cols-4 .landing-photogrid-zone { grid-template-columns: repeat(4, minmax(0, 1fr)); }

@media (max-width: 640px) {
