.landing-block a svg { width: 17px; }

.landing-block-hero { width: min(1240px, calc(100% - 48px)); min-height: 700px; padding: 60px 0 90px; display: grid; grid-template-columns: minmax(0, .92fr) minmax(400px, 1.08fr); align-items: center; gap: 76px; }
.landing-block-hero-copy { position: relative; z-index: 2; }
