.landing-block-hero figure img { width: 100%; height: 100%; object-fit: cover; display: block; }
.landing-block-hero.layout-split figure { border-radius: 8px; box-shadow: 24px 28px 0 #e5e8eb; }
.landing-block-hero.layout-product { min-height: 740px; grid-template-columns: minmax(0, .82fr) minmax(460px, 1.18fr); }
.landing-block-hero.layout-product figure { height: 610px; border: 1px solid #e5e8eb; background: #f2f4f6; }
.landing-block-hero.layout-product figure img { object-fit: contain; padding: 40px; }
.landing-block-hero.layout-course figure { border-radius: 8px 8px 80px 8px; }
.landing-block-hero.layout-course .landing-block-hero-copy { padding: 40px; border-left: 5px solid var(--landing-accent, #1b64da); }
.landing-block-hero.layout-tech { width: 100%; min-height: 760px; padding: 90px max(24px, calc((100vw - 1180px) / 2)); background: #191f28; color: #fff; }
