.landing-block-hero.layout-immersive { width: 100%; max-width: none; min-height: 790px; padding: 90px max(24px, calc((100vw - 1180px) / 2)); grid-template-columns: minmax(0, 760px); align-items: end; color: #fff; position: relative; isolation: isolate; }
.landing-block-hero.layout-immersive:after { content: ""; position: absolute; z-index: -1; inset: 0; background: #101318a3; }
