  .mission-cockpit-head { min-height: 0; padding: 19px 16px 16px; gap: 14px; }
  .mission-cockpit-head h3 { font-size: 21px; line-height: 1.4; }
  .mission-cockpit-head p { font-size: 11px; line-height: 1.6; }
  .mission-head-progress { width: 100%; grid-template-columns: minmax(0, 1fr) auto; }
  .mission-head-progress > span strong { font-size: 16px; }
  .mission-results-shortcut { min-height: 38px; padding: 0 9px; font-size: 10px; }
  .mission-extra-tools { margin: 10px 12px 0; }
