  .mission-single-action > div:first-of-type > b { width: 34px; height: 34px; }
  .mission-single-action > div:first-of-type > strong { padding-top: 2px; font-size: 15px; line-height: 1.65; }
  .mission-single-action .mission-evidence-options { grid-template-columns: 1fr; }
