/* Support assistant: quick help should read like a conversation, not a menu. */
.support-chat-home {
  gap: 10px;
}
.support-chat-bot-message {
  width: 92%;
  max-width: 340px;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  align-items: start;
  gap: 8px;
}
.support-chat-bot-message > span {
  width: 30px;
  height: 30px;
  border: 1px solid #cccae3;
  border-radius: 9px;
  background: #fff;
  color: #3272db;
  display: grid;
  place-items: center;
}
.support-chat-bot-message > span svg {
  width: 16px;
}
.support-chat-bot-message > div {
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid #cccae3;
  border-radius: 4px 12px 12px;
  background: #fff;
  box-shadow: 0 5px 14px rgba(20, 57, 43, .05);
}
.support-chat-bot-message strong {
  color: #0d0a2c;
  display: block;
  font-size: 12px;
  line-height: 1.45;
}
.support-chat-bot-message p {
  margin: 4px 0 0;
  color: #5f5c7f;
  font-size: 9px;
  line-height: 1.55;
}
.support-chat-bot-message.compact {
  margin-top: 2px;
}
.support-chat-choice-bubbles {
  width: 100%;
  padding-left: 38px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}
.support-chat-choice-bubbles button {
  width: fit-content;
  max-width: 88%;
  min-height: 38px;
  padding: 8px 12px;
  border: 1px solid #b0b8c1;
  border-radius: 14px 4px 14px 14px;
  background: #eef6ff;
  color: #3272db;
  cursor: pointer;
  overflow-wrap: anywhere;
  text-align: left;
  font-size: 10px;
  font-weight: 750;
  line-height: 1.5;
  transition: background .16s ease, border-color .16s ease, color .16s ease, transform .16s ease;
}
.support-chat-choice-bubbles button:hover,
.support-chat-choice-bubbles button:focus-visible {
  border-color: #3272db;
  background: #3272db;
  color: #fff;
  outline: 0;
  transform: translateX(-2px);
}
.support-chat-choice-bubbles button.back {
  border-color: #cccae3;
  background: #fff;
  color: #585667;
}
.support-chat-choice-bubbles button.operator {
  border-color: #cccae3;
  background: #fff;
  color: #333d4b;
}
.support-chat-selected-bubble {
  width: 100%;
  display: flex;
  justify-content: flex-end;
}
.support-chat-selected-bubble > span {
  max-width: 84%;
  padding: 9px 12px;
  border-radius: 14px 4px 14px 14px;
  background: #3272db;
  color: #fff;
  overflow-wrap: anywhere;
  font-size: 10px;
  font-weight: 750;
  line-height: 1.5;
  box-shadow: 0 5px 14px rgba(49, 130, 246, .14);
}
.support-chat-conversation .support-chat-messages article.customer > p {
  border-radius: 12px 4px 12px 12px;
  background: #3272db;
}
.support-chat-conversation .support-chat-messages article.admin > p,
.support-chat-conversation .support-chat-messages article.assistant > p {
  border-radius: 4px 12px 12px;
}
.support-chat-widget.open .support-chat-panel {
  animation: support-panel-enter .24s cubic-bezier(.2, .8, .2, 1) both;
  transform-origin: right bottom;
}
.support-chat-conversation .support-chat-messages {
  scroll-behavior: smooth;
  overscroll-behavior: contain;
  overflow-anchor: auto;
  scrollbar-gutter: stable;
}
.support-chat-saved-history {
  display: contents;
}
.support-chat-history-toggle {
  min-height: 32px;
  margin: 2px auto 8px;
  padding: 0 12px;
  border: 1px solid #cccae3;
  border-radius: 999px;
  background: rgba(255, 255, 255, .94);
  color: #585667;
  position: sticky;
  top: 0;
  z-index: 5;
  cursor: pointer;
  font-size: 9px;
  font-weight: 800;
  line-height: 1;
  box-shadow: 0 4px 12px rgba(30, 54, 44, .07);
  backdrop-filter: blur(10px);
}
.support-chat-history-toggle:hover,
.support-chat-history-toggle:focus-visible {
  border-color: #8b95a1;
  color: #3272db;
  outline: 0;
}
.support-chat-thinking {
  width: fit-content;
  min-height: 38px;
  padding: 8px 12px 8px 8px;
  border: 1px solid #cccae3;
  border-radius: 4px 13px 13px;
  background: #fff;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  box-shadow: 0 5px 14px rgba(20, 57, 43, .05);
  animation: support-bubble-left .24s cubic-bezier(.2, .8, .2, 1) both;
}
.support-chat-thinking > span {
  width: 23px;
  height: 23px;
  margin-right: 2px;
  border-radius: 7px;
  background: #eef6ff;
  color: #3272db;
  display: grid;
  place-items: center;
}
.support-chat-thinking > span svg {
  width: 13px;
}
.support-chat-thinking > i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #5f5c7f;
  animation: support-thinking-dot 1s ease-in-out infinite;
}
.support-chat-thinking > i:nth-of-type(2) {
  animation-delay: .14s;
}
.support-chat-thinking > i:nth-of-type(3) {
  animation-delay: .28s;
}
.support-chat-bot-message {
  animation: support-bubble-left .25s cubic-bezier(.2, .8, .2, 1) both;
}
.support-chat-selected-bubble,
.support-chat-messages article.customer {
  animation: support-bubble-right .24s cubic-bezier(.2, .8, .2, 1) both;
}
.support-chat-messages article.admin,
.support-chat-messages article.assistant {
  animation: support-bubble-left .24s cubic-bezier(.2, .8, .2, 1) both;
}
.support-chat-choice-bubbles button {
  animation: support-choice-enter .22s ease both;
}
.support-chat-choice-bubbles button:nth-child(2) { animation-delay: .025s; }
.support-chat-choice-bubbles button:nth-child(3) { animation-delay: .05s; }
.support-chat-choice-bubbles button:nth-child(4) { animation-delay: .075s; }
.support-chat-choice-bubbles button:nth-child(5) { animation-delay: .1s; }
.support-chat-choice-bubbles button:nth-child(6) { animation-delay: .125s; }
.support-chat-choice-bubbles button:nth-child(7) { animation-delay: .15s; }
.support-chat-choice-bubbles button:nth-child(8) { animation-delay: .175s; }
.support-chat-input-row > button:not(:disabled) svg {
  animation: support-send-ready 1.8s ease-in-out infinite;
}

@keyframes support-panel-enter {
  from { opacity: 0; transform: translateY(12px) scale(.98); }
  to { opacity: 1; transform: none; }
}
@keyframes support-bubble-left {
  from { opacity: 0; transform: translateX(-8px) translateY(4px); }
  to { opacity: 1; transform: none; }
}
@keyframes support-bubble-right {
  from { opacity: 0; transform: translateX(8px) translateY(4px); }
  to { opacity: 1; transform: none; }
}
@keyframes support-choice-enter {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
@keyframes support-send-ready {
  0%, 100% { transform: translateX(0); }
  50% { transform: translateX(2px); }
}
@keyframes support-thinking-dot {
  0%, 60%, 100% { opacity: .35; transform: translateY(0); }
  30% { opacity: 1; transform: translateY(-3px); }
}

@media (max-width: 640px) {
  .support-chat-bot-message {
    max-width: 330px;
  }
  .support-chat-choice-bubbles {
    padding-left: 34px;
  }
  .support-chat-choice-bubbles button {
    max-width: 92%;
    min-height: 40px;
    padding: 9px 12px;
    font-size: 11px;
  }
  .support-chat-selected-bubble > span {
    font-size: 11px;
  }
  .support-chat-history-toggle {
    min-height: 34px;
    font-size: 10px;
  }
  .support-chat-widget.open .support-chat-panel {
    animation-name: support-panel-enter-mobile;
    transform-origin: center bottom;
  }
}

@keyframes support-panel-enter-mobile {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .support-chat-widget.open .support-chat-panel,
  .support-chat-bot-message,
  .support-chat-selected-bubble,
  .support-chat-messages article,
  .support-chat-choice-bubbles button,
  .support-chat-input-row > button svg,
  .support-chat-thinking,
  .support-chat-thinking > i {
    animation: none;
  }
}

/* Icon-free action system */
:root {
  --action-blue: #3272db;
  --action-blue-hover: #3a2ddb;
  --action-blue-soft: #efeefb;
  --action-blue-soft-hover: #e4e2fb;
  --action-blue-text: #3a2ddb;
}

:where(button, a):focus-visible {
  outline-color: var(--action-blue);
}

/* 플랜 빌더(.plan-ui)는 자체 디자인 체계를 쓰므로 이 정규화에서 제외한다.
   여기 !important가 그쪽 모듈 CSS를 전부 덮어써서 모서리·굵기 위계가 뭉개졌다. */
button:not(.brand):not(.mobile-report-backdrop):not(.plan-ui *) {
  min-height: var(--btn-h);
  border-radius: var(--radius) !important;
  letter-spacing: 0 !important;
  font-weight: 700 !important;
  box-shadow: none !important;
  transform: none !important;
}

/* 같은 이유로 플랜 빌더의 아이콘은 숨기지 않는다 */
button:not(.plan-ui *) svg,
.account-link svg,
.small-start svg,
.home-sample-preview svg,
.manual-project-start svg,
.landing-block a svg,
.public-landing-hero-copy button svg,
.preview-lead-form button svg {
  display: none !important;
}

/* These two are intentionally icon-only (text removed), so re-show their icons
   despite the global "buttons use text, not icons" rule above. */
.account-link svg,
.mobile-report-menu-trigger svg {
  display: inline-block !important;
  width: 18px;
  height: 18px;
}

/*
 * 아이콘만 든 껍데기 span은 옛 화면에서 자리만 먹어 감춘다.
 * 플랜 빌더(.plan-ui)는 위의 svg 규칙과 같은 이유로 제외한다 — 자체 디자인
 * 체계를 쓰고, 거기서는 아이콘 칸이 의도된 구성 요소다(문서 화면의 내려받기
 * 버튼이 이 규칙에 걸려 아이콘 칸이 통째로 사라졌다).
 */
button:not(.plan-ui *) > span:has(> svg:only-child),
button:not(.plan-ui *) > i:has(> svg:only-child) {
  display: none !important;
}

