  background: #161c2d; color: #fff; box-shadow: none; grid-template-columns: minmax(0, 1fr) minmax(0, 440px); gap: 80px; align-items: center;
}
.public-landing.kit .public-lead-section > div > small { color: #68d585; font-size: 13px; letter-spacing: .125em; text-transform: uppercase; }
.public-landing.kit .public-lead-section > div h2 { color: #fff; font-size: 36px; line-height: 48px; letter-spacing: -.033em; }
.public-landing.kit .public-lead-section > div > p { color: #ffffffb8; font-size: 19px; line-height: 32px; }
.public-landing.kit .public-lead-section form,
.public-landing.kit .public-lead-ready,
.public-landing.kit .public-lead-success { padding: 34px 30px; border-radius: 10px; background: #fff; color: #161c2d; }
.public-landing.kit .public-lead-section form input:not([type="checkbox"]),
.public-landing.kit .public-lead-section form textarea { min-height: 50px; border: 1px solid #e3e6ee; border-radius: 6px; font-size: 15px; background: #fff; }
.public-landing.kit .public-lead-section form button[type="submit"] { min-height: 59px; border-radius: 6px; font-size: 17px; font-weight: 700; }
.public-landing.kit .public-lead-section form :where(p, small, strong) { color: #161c2d; }
.public-landing.kit .public-lead-section form small { color: #5d6270; }
.public-landing.kit .public-landing-footer { background: #161c2d; color: #ffffffb8; }
.public-landing.kit .public-landing-footer :where(strong, p, small, a) { color: inherit; }
.public-landing.kit .public-kit-credit a { color: #ffffff80; text-decoration: underline; text-underline-offset: 3px; }

/* ── 640 이하 — 한 열 (태블릿 모드 없음) ─────────────────────── */
@media (max-width: 640px) {
  .landing-block-page.kit { --kit-pad: 20px; }
  .landing-block-page.kit .landing-block { padding-top: 64px; padding-bottom: 64px; }
  .landing-block-page.kit .landing-block-hero { padding: 72px 20px 64px; gap: 32px; grid-template-columns: 1fr; }
  .landing-block-page.kit .landing-block-hero h1 { font-size: 36px; line-height: 44px; }
  .landing-block-page.kit .landing-block-hero p { font-size: 17px; line-height: 28px; }
  .landing-block-page.kit .landing-block h2 { font-size: 28px; line-height: 38px; }
  .landing-block-page.kit .landing-block p { font-size: 16px; line-height: 27px; }
  .landing-block-page.kit .landing-block-stats > div,
  .landing-block-page.kit .landing-block-features > div,
  .landing-block-page.kit .landing-block-process ol,
  .landing-block-page.kit .landing-block-price ul,
  .landing-block-page.kit .landing-block-faq dl,
  .landing-block-page.kit .landing-block-reviews > div { grid-template-columns: 1fr !important; gap: 20px; }
  .landing-block-page.kit .landing-block-stats strong { font-size: 36px; line-height: 44px; }
  .landing-block-page.kit .landing-block-story { gap: 28px; }
  .landing-block-page.kit .landing-block-price b { font-size: 36px; line-height: 44px; }
  .landing-block-page.kit .landing-video-frame { border-radius: 12px; }
  .landing-block-page.kit-shop .landing-block-hero.layout-immersive,
  .landing-block-page.kit-shop .landing-block-story,
  .landing-block-page.kit-shop .landing-block-reviews,
  .landing-block-page.kit-shop .landing-block-cta { width: calc(100% - 16px); margin: 8px auto; padding-left: 20px; padding-right: 20px; }
  .landing-block-page.kit-shop .landing-block-hero.layout-immersive { min-height: 520px; }
  .landing-block-page.kit-shop .landing-block-cta :where(h2) { font-size: 36px; line-height: 44px; }
  .landing-block-page.kit-saas .landing-block-hero h1,
  .landing-block-page.kit-b2b .landing-block-hero h1 { font-size: 36px; line-height: 44px; }
  .landing-block-page.kit-app .landing-block-hero figure { width: min(240px, 100%); }
  .landing-block-page.kit-b2b .landing-block-hero figure { justify-self: center; }
  .public-landing.kit .public-lead-section { padding: 64px 20px; grid-template-columns: 1fr; gap: 32px; }
  .public-landing.kit .public-lead-section > div h2 { font-size: 28px; line-height: 38px; }
}

/* 사진 위 첫 화면(consult·cowork·shop) — 킷은 왼쪽 정렬이고 글은 전부 흰색이다.
   기본 immersive 배치가 가운데로 모으고 라벨을 강조색으로 칠해 파란 바탕에 파란
   글자가 됐다. */
.landing-block-page.kit .landing-block-hero.layout-immersive { text-align: left; justify-items: start; }
.landing-block-page.kit .landing-block-hero.layout-immersive .landing-block-hero-copy > span { color: #ffffffd9; }
.landing-block-page.kit .landing-block-hero.layout-immersive p { color: #ffffffd6; }
.landing-block-page.kit .landing-block-hero.layout-immersive.no-image { text-align: center; justify-items: center; }
/* 킷은 칸 안의 글을 가운데 모으지 않는다 — 제목만 가운데, 본문·카드는 왼쪽 */
.landing-block-page.kit .landing-block-story > div,
.landing-block-page.kit .landing-block-price li,
.landing-block-page.kit .landing-block-faq dl,
.landing-block-page.kit .landing-block-offer { text-align: left; }
.landing-block-page.kit .landing-block-faq dl > div { border-top: 1px solid #e9ecf2; padding-top: 24px; }
/* 사진 옆 글(split·tech)도 왼쪽 정렬 — 킷에서 가운데 모으는 첫 화면은 saas·product 뿐 */
.landing-block-page.kit .landing-block-hero.layout-split,
.landing-block-page.kit .landing-block-hero.layout-tech { text-align: left; justify-items: start; }
.landing-block-page.kit .landing-block-hero.layout-split .landing-block-hero-copy,
.landing-block-page.kit .landing-block-hero.layout-tech .landing-block-hero-copy { justify-self: start; }
.landing-block-page.kit-saas .landing-block-hero.layout-split { text-align: center; justify-items: center; }

/* ── Brainwave 킷 페이지 무대 ───────────────────────────────────
 * 1600 캔버스를 보는 폭만큼 줄인다. 글·칸은 킷 좌표 그대로다. */
.bw-stage { position: relative; width: 100%; overflow: hidden; background: #fff; container-type: inline-size; }
/* 비율 = 보는 폭 / 1600. tan(atan2(a, b)) 는 a/b 를 숫자로 돌려준다(길이끼리 나눗셈이 안 되므로). */
.bw-fit { --bw-scale: tan(atan2(100cqw, calc(var(--bw-w, 1600) * 1px))); position: relative; width: 100%; height: calc(var(--bw-h, 1000) * 1px * var(--bw-scale)); }
@supports not (width: tan(atan2(1px, 1px))) {
  .bw-fit { --bw-scale: var(--bw-js-scale, 1); }
}
.bw-canvas { position: absolute; left: 0; top: 0; transform-origin: 0 0; transform: scale(var(--bw-scale)); font-family: Pretendard, "Pretendard Variable", "Apple SD Gothic Neo", sans-serif; color: #161c2d; }
.bw-canvas :where(p, div, span, img), .bw-mobile :where(p, div, span, img) { margin: 0; padding: 0; box-sizing: border-box; }
.bw-canvas p, .bw-mobile p { white-space: pre-wrap; }
.bw-canvas img, .bw-mobile img { display: block; }
/* 불러오는 중 — 흰 바탕에 워드마크와 진행 막대만(Wix 로딩을 본뜬 간결형) */
.bw-loading { min-height: 320px; background: #fff; display: grid; place-content: center; justify-items: center; gap: 26px; }
.bw-loading-word { font-size: clamp(24px, 4vw, 34px); letter-spacing: .04em; color: #161c2d; font-weight: 300; }
.bw-loading-word b { font-weight: 800; }
.bw-loading-bar { position: relative; width: min(340px, 60vw); height: 6px; border-radius: 999px; background: #e8eaf1; overflow: hidden; }
.bw-loading-bar i { position: absolute; inset: 0 auto 0 0; width: 42%; border-radius: inherit; background: linear-gradient(90deg, #7aa5ff, #473bf0); animation: bwLoadSlide 1.3s ease-in-out infinite; }
@keyframes bwLoadSlide { from { transform: translateX(-110%); } to { transform: translateX(340%); } }
@media (prefers-reduced-motion: reduce) { .bw-loading-bar i { animation: none; width: 100%; } }
@keyframes bw-shimmer { from { background-position: 100% 0 } to { background-position: 0 0 } }
.bw-error { padding: 24px; color: #b91c1c; }

/* ── Brainwave 자리 편집기 ───────────────────────────────────── */
.bw-editor { display: grid; grid-template-rows: auto auto 1fr auto; background: #e9ecf2; }
.bw-editor-bar { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 10px 16px; background: #fff; border-bottom: 1px solid #e3e6ee; }
.bw-editor-left { display: flex; align-items: center; gap: 14px; min-width: 0; flex-wrap: wrap; }
.bw-editor-left strong { font-size: 15px; }
.bw-editor-left small { color: #5d6270; font-size: 12.5px; }
.bw-editor-page { display: flex; align-items: center; gap: 8px; font-size: 13px; }
.bw-editor-page select { min-height: 34px; padding: 0 10px; border: 1px solid #dfe3ea; border-radius: 6px; background: #fff; font-size: 13px; }
.bw-editor-right { display: flex; align-items: center; gap: 6px; }
.bw-editor-right button { min-height: 36px; min-width: 36px; padding: 0 10px; border: 1px solid #dfe3ea; border-radius: 6px; background: #fff; display: inline-flex; align-items: center; gap: 6px; font-size: 13px; cursor: pointer; }
.bw-editor-right button:disabled { opacity: .4; cursor: default; }
.bw-editor-right button svg { width: 16px; height: 16px; }
.bw-editor-right .bw-editor-save { background: #473bf0; border-color: #473bf0; color: #fff; font-weight: 700; }
.bw-editor-error { margin: 0; padding: 8px 16px; background: #fff1f1; color: #b91c1c; font-size: 13px; }
.bw-editor-stage { overflow: auto; padding: 20px; }
.bw-editor-canvas { position: relative; max-width: 1600px; margin: 0 auto; box-shadow: 0 20px 60px rgba(22, 28, 45, .12); }
.bw-editor-canvas [data-bw-text] { cursor: text; outline: 1px dashed transparent; outline-offset: 2px; transition: outline-color .12s; }
.bw-editor-canvas [data-bw-text]:hover { outline-color: #473bf0aa; }
.bw-editor-canvas [data-bw-text][contenteditable="plaintext-only"] { outline: 2px solid #473bf0; background: #473bf012; }
.bw-editor-canvas [data-bw-image] { cursor: pointer; }
.bw-editor-canvas [data-bw-image]:hover { outline: 3px solid #473bf0; outline-offset: -3px; }
/* 버튼 자리 — 누르면 글자·이동을 정하는 판이 열린다 */
.bw-editor-canvas [data-bw-btn] { cursor: pointer; }
.bw-editor-canvas [data-bw-btn]:hover { outline: 3px solid #68d585; outline-offset: 2px; border-radius: 6px; }

/* 버튼 설정 판 — 텍스트 판과 같은 자리(오른쪽 도킹), 폰에서는 아래 시트 */
.bw-btn-panel { position: fixed; top: 64px; right: 14px; z-index: 90; width: min(320px, calc(100vw - 28px)); max-height: calc(100dvh - 130px); overflow: auto; padding: 16px; border-radius: 14px; background: #fff; border: 1px solid #e3e6ee; box-shadow: 0 18px 60px rgba(22, 28, 45, .22); display: grid; gap: 12px; animation: bwInsIn .18s ease backwards; }
@media (max-width: 640px) { .bw-btn-panel { top: auto; right: 10px; left: 10px; bottom: 10px; width: auto; max-height: 60dvh; } }
.bw-btn-panel > strong { font-size: 15px; }
.bw-btn-opts { display: grid; gap: 8px; }
.bw-btn-opts label { display: flex; align-items: baseline; gap: 8px; font-size: 14px; font-weight: 700; cursor: pointer; }
.bw-btn-opts small { font-weight: 400; color: #8181a5; font-size: 12px; }
.bw-btn-url, .bw-btn-label input { min-height: 42px; padding: 0 12px; border: 1px solid #dfe3ea; border-radius: 8px; font-size: 14px; width: 100%; }
.bw-btn-label { display: grid; gap: 5px; font-size: 12.5px; color: #5e5e72; }
.bw-btn-actions { display: flex; justify-content: flex-end; gap: 8px; }
.bw-btn-actions button { min-height: 38px; padding: 0 16px; border: 1px solid #dfe3ea; border-radius: 8px; background: #fff; font-size: 13.5px; font-weight: 700; cursor: pointer; }
.bw-btn-actions .bw-btn-apply { background: #473bf0; border-color: #473bf0; color: #fff; }

/* 등장 애니메이션 — 공개 화면·미리보기. 숨김은 JS 가 .bw-anim 을 붙일 때만 생긴다 */
.bw-anim { opacity: 0; transform: translateY(16px); transition: opacity .55s ease, transform .55s ease; }
.bw-anim.bw-in { opacity: 1; transform: none; }
.bw-editor-uploading { position: absolute; inset: 0; display: grid; place-items: center; background: #ffffffb8; font-weight: 700; color: #161c2d; gap: 8px; }
.bw-editor-hint { margin: 0; padding: 8px 16px; background: #fff; border-top: 1px solid #e3e6ee; color: #5d6270; font-size: 12.5px; display: flex; align-items: center; gap: 8px; }
.bw-editor-hint svg { width: 15px; height: 15px; flex: none; }
.bw-editor-hint b { color: #161c2d; white-space: nowrap; }

/* 모바일에서의 에디터 — 바를 두 줄로 정돈하고 폰 베젤 장식은 뺀다 (2026-08-25 정리) */
@media (max-width: 640px) {
  .bw-editor-bar { flex-wrap: wrap; gap: 8px 10px; padding: 8px 10px; }
  .bw-editor-left { order: 2; flex: 1 1 100%; flex-wrap: nowrap; gap: 8px; overflow-x: auto; -webkit-overflow-scrolling: touch; }
  .bw-editor-left strong { display: none; }
  .bw-editor-left > * { flex: none; }
  .bw-editor-pick-x { display: none; }
  .bw-editor-left { gap: 6px; }
  .bw-editor-pick, .bw-editor-preview { padding: 0 9px; }
  .bw-editor-views button { padding: 0 9px; }
  .bw-editor-right { order: 1; flex: 1 1 100%; justify-content: flex-end; }
  .bw-editor-stage { padding: 10px; }
  .bw-editor-canvas.view-mobile { border: 0; border-radius: 12px; overflow: hidden; }
  .bw-ai { padding: 10px; }
  .bw-ai-row { flex-direction: column; }
  .bw-ai-row button { justify-content: center; }
}
/* 공개 페이지 — 킷 머리글이 있으니 우리 머리글은 없고, 문의 양식·법정 푸터만 아래에 */
.public-landing.brainwave .public-lead-section { margin-top: 0; }
.bw-editor-right button svg { width: 16px; height: 16px; stroke: #161c2d; }
.bw-editor-right .bw-editor-save svg { stroke: #fff; }
/* 전역 letter-spacing:0 !important 를 이기기 위한 자간 변수 — 킷 값 그대로 */
.bw-canvas [style*="--bw-ls"], .bw-mobile [style*="--bw-ls"] { letter-spacing: var(--bw-ls) !important; }
.bw-canvas [data-bw-btn], .bw-mobile [data-bw-btn] { cursor: pointer; }
.bw-canvas [data-bw-btn]:focus-visible { outline: 3px solid #473bf0; outline-offset: 2px; }

/* 홈 예시 띠 — 킷 페이지 첫 화면 스크린샷 */
.home-peek-track li .peek-shot { display: block; width: 100%; aspect-ratio: 640 / 559; object-fit: cover; object-position: top; background: #f4f7fa; }
/* 한글은 띄어쓰기 단위로 줄을 바꾼다 — 킷의 break-word 는 글자 중간을 자른다("같|이") */
.bw-canvas [style], .bw-mobile [style] { word-break: keep-all !important; overflow-wrap: break-word; }

/* 도메인 상품 결제 유도 */
.landing-domain-connector .domain-buy-cta { display: flex; justify-content: center; align-items: center; min-height: 48px; margin: 12px 0; border-radius: 8px; background: #3272db; color: #fff; font-weight: 700; font-size: 14px; text-decoration: none; }
.landing-domain-connector .domain-term { margin: 0 0 10px; padding: 8px 12px; border-radius: 8px; background: #f6f5ff; color: #585667; font-size: 12.5px; }
.landing-domain-connector .domain-term.soon { background: #fff7e6; color: #8a5a00; }
.landing-domain-connector .domain-term.expired { background: #fff1f1; color: #b91c1c; }
.landing-domain-connector .domain-term a { margin-left: 8px; font-weight: 700; color: inherit; text-decoration: underline; }

/* AI 로 고치기 */
.bw-editor.with-ai { grid-template-rows: auto auto auto 1fr auto; }
.bw-editor-right .bw-editor-ai { gap: 6px; font-weight: 700; }
.bw-editor-right .bw-editor-ai.on { background: #161c2d; border-color: #161c2d; color: #fff; }
.bw-editor-right .bw-editor-ai.on svg { stroke: #fff; }
.bw-ai { padding: 10px 16px 12px; background: #fff; border-bottom: 1px solid #e3e6ee; display: grid; gap: 8px; }
.bw-ai-row { display: flex; gap: 8px; }
.bw-ai-row input { flex: 1; min-height: 42px; padding: 0 14px; border: 1px solid #dfe3ea; border-radius: 8px; font-size: 14px; }
.bw-ai-row input:focus { outline: 2px solid #473bf0; border-color: transparent; }
.bw-ai-row button { min-height: 42px; padding: 0 16px; border: 0; border-radius: 8px; background: #473bf0; color: #fff; font-weight: 700; font-size: 14px; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; white-space: nowrap; }
.bw-ai-row button:disabled { opacity: .45; cursor: default; }
.bw-ai-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 14px; font-size: 12.5px; color: #5d6270; }
.bw-ai-meta b { color: #161c2d; }
.bw-ai-meta a { color: #473bf0; font-weight: 700; text-decoration: underline; text-underline-offset: 3px; }
.bw-ai-meta em { font-style: normal; color: #161c2d; }
.builder-switch-kit { position: fixed; right: 16px; bottom: 92px; z-index: 70; display: inline-flex; align-items: center; gap: 8px; padding: 10px 14px; border: 0; border-radius: 10px; background: #161c2d; color: #fff; font-size: 13px; font-weight: 700; box-shadow: 0 10px 30px rgba(22,28,45,.3); cursor: pointer; }

/* ── 킷 페이지 홈페이지 화면(/plan/homepage) ───────────────────── */
.hk { display: grid; gap: 16px; }
.hk-top { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.hk-back { flex: none; width: 32px; height: 32px; border: 1px solid #e6e6ef; border-radius: 8px; background: #fff; color: #55586a; font-size: 14px; display: grid; place-items: center; text-decoration: none; }
.hk-top .hk-actions { margin-left: auto; }
.hk-top h3 { margin: 0 0 3px; font-size: 20px; font-weight: 800; letter-spacing: -.01em; line-height: 1.25; }
.hk-url { margin: 0; display: flex; align-items: center; gap: 10px; font-size: 13px; color: #8181a5; }
.hk-url span { padding: 2px 8px; border-radius: 999px; background: #f0f0f5; color: #1c1d21; font-weight: 700; font-size: 11.5px; }
.hk-url a { display: inline-flex; align-items: center; gap: 4px; color: #1c1d21; text-decoration: underline; text-underline-offset: 3px; }
.hk-actions { display: flex; gap: 8px; }
.hk-actions button { min-height: 42px; padding: 0 16px; border: 1px solid #e1e1e8; border-radius: 10px; background: #fff; color: #1c1d21; font-weight: 700; font-size: 14px; display: inline-flex; align-items: center; gap: 7px; cursor: pointer; }
.hk-actions .hk-primary { background: #3272db; border-color: #3272db; color: #fff; }
.hk-actions button:disabled { opacity: .5; cursor: default; }
.hk-msg { margin: -6px 0 0; font-size: 13px; color: #3272db; font-weight: 700; }
/* 주된 행동 — 큰 버튼 둘 (2026-08-25 개편) */
/* minmax(0,…) 필수 — 부제(nowrap)가 최소폭을 밀어 레이아웃 뷰포트를 494px 로 벌렸었다 */
.hk-cta { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.hk-cta-btn { display: flex; align-items: center; gap: 12px; min-height: 64px; padding: 10px 16px; border: 1.5px solid #e1e1e8; border-radius: 14px; background: #fff; color: #1c1d21; text-align: left; cursor: pointer; }
.hk-cta-btn svg { flex: none; color: #3272db; }
.hk-cta-btn > span { flex: 1; min-width: 0; }
.hk-cta-btn strong { display: block; font-size: 15px; letter-spacing: -.01em; }
.hk-cta-btn small { display: block; margin-top: 2px; font-size: 12px; color: #8181a5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.hk-cta-btn:hover { border-color: #3272db; }
.hk-cta-primary { background: #3272db; border-color: #3272db; color: #fff; }
.hk-cta-primary svg { color: #fff; }
.hk-cta-primary small { color: rgba(255, 255, 255, .75); }
.hk-cta-primary:hover { border-color: #2a62bd; background: #2a62bd; }
@media (max-width: 420px) { .hk-cta { grid-template-columns: 1fr; } }

/* 공개 전 주소 — 링크가 아니라 안내 */
.hk-url-pending { font-style: normal; color: #8181a5; }

/* 접이식 카드 */
.hk-fold { border: 1px solid #e6e6ee; border-radius: 14px; background: #fff; }
.hk-fold summary { list-style: none; display: flex; align-items: center; gap: 12px; padding: 15px 18px; cursor: pointer; }
.hk-fold summary::-webkit-details-marker { display: none; }
.hk-fold-ic { flex: none; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: #f0f4fc; color: #3272db; }
.hk-fold-tt { flex: 1; min-width: 0; }
.hk-fold-tt strong { display: flex; align-items: center; gap: 8px; font-size: 15px; }
/* 힌트에 nowrap 을 주면 min-content 가 문장 전체 폭이 되어 모바일 레이아웃 뷰포트를 벌린다 — 줄바꿈으로 둔다 */
.hk-fold-tt small { display: block; margin-top: 2px; color: #8181a5; font-size: 12.5px; line-height: 1.5; }
.hk-fold-chev { flex: none; color: #8181a5; transition: transform .15s; }
.hk-fold[open] .hk-fold-chev { transform: rotate(180deg); }
.hk-fold-body { padding: 2px 18px 18px; border-top: 1px solid #f0f0f5; padding-top: 14px; }
.hk-badge { padding: 2px 9px; border-radius: 999px; background: #f0f0f5; color: #5e5e72; font-style: normal; font-weight: 700; font-size: 11.5px; white-space: nowrap; }
.hk-badge-warn { background: #fdeaea; color: #c0392b; }
.hk-badge-ok { background: #e6f6ec; color: #1d7a45; }
.hk-badge-info { background: #e8f0fd; color: #3272db; }
/* 도메인 카드의 자체 제목은 요약 줄과 겹쳐서 숨긴다 — 연결 상태 표시(em)는 남긴다 */
.hk-fold-body .domain-connector-title > svg, .hk-fold-body .domain-connector-title > span { display: none; }
.hk-fold-body .landing-domain-connector { border: 0; padding: 0; box-shadow: none; }

.hk-preview { border: 1px solid #e6e6ee; border-radius: 14px; background: #fff; overflow: hidden; }
.hk-preview-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 16px; border-bottom: 1px solid #eeeef3; }
.hk-preview-head strong { font-size: 14px; }
.hk-edit { min-height: 36px; padding: 0 14px; border: 0; border-radius: 8px; background: #3272db; color: #fff; font-weight: 700; font-size: 13px; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; }
.hk-preview-body { position: relative; display: block; width: 100%; max-height: 560px; overflow: hidden; padding: 0; border: 0; background: #f5f5fa; text-align: left; cursor: pointer; }
.hk-preview-body .bw-stage { pointer-events: none; }
.hk-preview-cover { position: absolute; left: 0; right: 0; bottom: 0; padding: 34px 16px 14px; background: linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(255,255,255,.96) 55%); color: #1c1d21; font-size: 13px; font-weight: 700; display: flex; align-items: center; justify-content: center; gap: 8px; text-align: center; }
.hk-card { border: 1px solid #e6e6ee; border-radius: 14px; background: #fff; padding: 18px; }
.hk-card-head { display: flex; gap: 12px; align-items: flex-start; margin-bottom: 14px; }
.hk-card-head svg { flex: none; color: #3272db; margin-top: 2px; }
.hk-card-head strong { display: block; font-size: 15px; }
.hk-card-head small { color: #8181a5; font-size: 12.5px; line-height: 1.5; }
.hk-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px 14px; }
.hk-grid label { display: grid; gap: 5px; font-size: 12.5px; color: #5e5e72; }
.hk-grid label.wide { grid-column: 1 / -1; }
.hk-grid input:not([type="checkbox"]) { min-height: 40px; padding: 0 12px; border: 1px solid #e1e1e8; border-radius: 8px; font-size: 14px; color: #1c1d21; background: #fff; }
.hk-grid .slug-input { display: flex; align-items: center; border: 1px solid #e1e1e8; border-radius: 8px; overflow: hidden; }
.hk-grid .slug-input em { padding: 0 10px; background: #f5f5fa; color: #8181a5; font-style: normal; font-size: 13px; line-height: 40px; }
.hk-grid .slug-input input { border: 0; flex: 1; }
.hk-switch { display: flex !important; align-items: flex-start; gap: 10px; padding: 10px 12px; border-radius: 8px; background: #f5f5fa; }
.hk-switch input { margin-top: 3px; }
.hk-switch span { color: #1c1d21; font-weight: 700; font-size: 13.5px; }
.hk-switch small { display: block; margin-top: 2px; color: #8181a5; font-weight: 400; }
.hk-empty { margin: 0; color: #8181a5; font-size: 13px; }
.hk-leads { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.hk-leads li { display: flex; gap: 12px; padding: 12px; border-radius: 10px; background: #f5f5fa; }
.hk-leads i { width: 36px; height: 36px; border-radius: 50%; flex: none; display: grid; place-items: center; background: #3272db; color: #fff; font-style: normal; font-weight: 700; }
.hk-leads strong { display: block; font-size: 14px; }
.hk-leads span { font-size: 13px; color: #1c1d21; }
.hk-leads p { margin: 6px 0 0; font-size: 13px; color: #5e5e72; white-space: pre-wrap; }
.hk-leads small { display: block; margin-top: 4px; color: #8181a5; font-size: 11.5px; }
@media (max-width: 640px) { .hk-grid { grid-template-columns: 1fr; } .hk-actions { width: 100%; } .hk-actions button { flex: 1; justify-content: center; } }
.hk { padding-top: 10px; }
/* 킷 코드가 사진에 pointer-events:none 을 박아 둔다 — 편집 중에는 눌러야 한다 */
.bw-editor-canvas [data-bw-image] { pointer-events: auto !important; }

/* 템플릿 고르기 창 */
.bwtp { position: fixed; inset: 0; z-index: 120; background: rgba(22,28,45,.55); display: grid; place-items: center; padding: 20px; }
.bwtp-sheet { width: min(1100px, 100%); max-height: 90vh; display: grid; grid-template-rows: auto 1fr; border-radius: 16px; background: #fff; overflow: hidden; box-shadow: 0 30px 80px rgba(0,0,0,.3); }
.bwtp-sheet > header { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 16px 20px; border-bottom: 1px solid #e6e6ee; }
.bwtp-sheet > header strong { display: block; font-size: 17px; }
.bwtp-sheet > header small { color: #8181a5; font-size: 12.5px; }
.bwtp-sheet > header button { width: 36px; height: 36px; border: 1px solid #e1e1e8; border-radius: 8px; background: #fff; display: grid; place-items: center; cursor: pointer; }
.bwtp-body { overflow: auto; padding: 16px 20px 24px; display: grid; gap: 22px; }
.bwtp-body h4 { margin: 0 0 10px; font-size: 14px; }
.bwtp-body h4 small { margin-left: 8px; color: #8181a5; font-weight: 400; font-size: 12.5px; }
.bwtp-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 12px; }
.bwtp-grid button { position: relative; padding: 0; border: 2px solid #e6e6ee; border-radius: 12px; background: #fff; overflow: hidden; text-align: left; cursor: pointer; display: grid; }
.bwtp-grid button:hover { border-color: #b9b3ff; }
.bwtp-grid button.on { border-color: #3272db; }
.bwtp-grid img { display: block; width: 100%; aspect-ratio: 640 / 559; object-fit: cover; object-position: top; background: #f4f7fa; }
.bwtp-grid span { padding: 9px 10px; display: grid; gap: 1px; }
.bwtp-grid span b { font-size: 13px; }
.bwtp-grid span small { color: #8181a5; font-size: 11.5px; }
.bwtp-grid em { position: absolute; top: 8px; right: 8px; padding: 3px 8px; border-radius: 999px; background: #3272db; color: #fff; font-style: normal; font-size: 11px; font-weight: 700; }
.hk-preview-btns { display: flex; gap: 8px; }
.hk-pick { min-height: 36px; padding: 0 14px; border: 1px solid #e1e1e8; border-radius: 8px; background: #fff; color: #1c1d21; font-weight: 700; font-size: 13px; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; }
.bw-editor-pick { min-height: 34px; padding: 0 12px; border: 1px solid #dfe3ea; border-radius: 6px; background: #fff; font-size: 13px; font-weight: 700; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; }
.bw-editor-views { display: inline-flex; border: 1px solid #dfe3ea; border-radius: 6px; overflow: hidden; }
.bw-editor-views button { height: 34px; padding: 0 12px; border: 0; background: #fff; display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; cursor: pointer; color: #5d6270; white-space: nowrap; }
.bw-editor-views button.on { background: #161c2d; color: #fff; }
.bw-editor-canvas.view-mobile { border: 10px solid #161c2d; border-radius: 28px; }

/* 모바일 자동 재배치 */
.bw-stage.bw-mobile { height: auto; overflow: visible; }
.bwm-stack { position: relative; width: 100%; }
.bwm-bg { position: absolute; inset: 0; overflow: hidden; z-index: 0; }
.bwm-bg > * { position: absolute !important; inset: 0 !important; width: 100% !important; height: 100% !important; }
.bwm-bg img { object-fit: cover; }
.bwm-items { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; }
.bwm-leaf { position: relative; overflow: hidden; }
.bwm-frame { position: relative; transform-origin: 0 0; }
.bwm-frame > * { box-sizing: border-box; }
.bw-editor-preview { min-height: 34px; padding: 0 12px; border: 1px solid #dfe3ea; border-radius: 6px; background: #fff; font-size: 13px; font-weight: 700; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; }
.bw-editor-preview.on { background: #161c2d; border-color: #161c2d; color: #fff; }
.bw-editor-canvas.previewing [data-bw-text], .bw-editor-canvas.previewing [data-bw-image] { cursor: default; outline: none !important; }
.bw-editor-canvas.previewing [data-bw-text]:hover, .bw-editor-canvas.previewing [data-bw-image]:hover { outline: none !important; }
.bw-mobile .bwm-items { padding: 12px 16px; gap: 10px; }
.bw-mobile .bwm-items .bwm-items { padding: 0; }
.bw-stage.bw-mobile { font-family: Pretendard, "Pretendard Variable", "Apple SD Gothic Neo", sans-serif; color: #161c2d; line-height: 1.2; }
.bw-mobile :where(p, span, div) { font-size: inherit; }
.bwm-leaf.bwm-text { overflow: visible; height: auto; }
/* 흐름 배치 안의 글·사진은 가운데 — 세로 한 열에서는 축이 하나여야 정돈돼 보인다 */
.bwm-flow { position: relative; text-align: center; word-break: keep-all; }
.bwm-flow img { margin-inline: auto; }
.bwm-flow > * { position: relative !important; display: block; }

/* ────────────────────────────────────────────────────────────────
 * 폰에서 히어로가 화면 밖으로 밀리지 않게 못박는다.
 *
 * 실기기(사파리·카카오 인앱)에서 검색 알약과 상담 카드의 오른쪽이 잘려 보였다.
 * 넘치는 폭이 왼쪽 여백과 같았다 — 칸이 '여백을 뺀 폭'이 아니라 '화면 폭'만큼
 * 잡히고 여백 안쪽에서 시작해서, 딱 여백만큼 밖으로 나간 것이다.
 *
 * 이 칸들은 그리드 항목이고 그리드 항목의 기본값은 min-width: auto —
 * "내용의 최소 너비보다는 작아지지 않겠다". 아이폰이 같은 한글을 조금 더 넓게
 * 그리면 칸이 줄지 않고 밀려나고, 조상의 overflow: hidden 이 그걸 잘라낸다.
 * 그래서 가로 스크롤이 아니라 '잘림'으로 보였다.
 *
 * 이 블록은 파일 맨 끝에 있어야 한다. 앞에 두었을 때는
 * `.simple-home-choice > div.home-hero-stage { max-width: none }`(위쪽)이
 * 더 강한 선택자로 덮어써서 아무 일도 하지 않았다 — 실제로 한 번 그렇게 놓쳤다.
 * ──────────────────────────────────────────────────────────────── */
@media (max-width: 640px) {
  .simple-home .simple-home-choice > div.home-hero-stage,
  .simple-home .simple-home-choice > .home-hero-copy,
  .simple-home .home-hero-copy .home-hero-actions,
  .simple-home .home-hero-stage .demo-card {
    min-width: 0;
    max-width: 100%;
  }

  /* 알약: 칸도, 그 안의 글자도 칸을 벌리지 못하게 */
  .simple-home .home-hero-actions > .hero-search {
    min-width: 0;
    max-width: 100%;
  }
  .simple-home .home-hero-actions > .hero-search > span,
  .simple-home .home-hero-actions > .hero-search input {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* 상담 카드 내부 — 장면이 바뀌어도 칸을 벌리지 않게 */
  .simple-home .demo-card,
  .simple-home .demo-card .demo-scene,
  .simple-home .demo-card .demo-chat-head,
  .simple-home .demo-card .demo-chat-body,
  .simple-home .demo-card .demo-chat-input,
  .simple-home .demo-card .demo-paper { min-width: 0; max-width: 100%; }
  .simple-home .demo-card :where(p, span, strong, b, em) { min-width: 0; overflow-wrap: anywhere; }
}

/* ────────────────────────────────────────────────────────────────
 * 폰에서 히어로 칸을 퍼센트로 계산하지 않는다.
 *
 * 사용자 아이폰(390px)의 진단이 잡아 준 것:
 *   div.home-hero-copy [hero-shell가 자름] 390 →410 @2.0s
 * 왼쪽 20px 여백 안에서 시작하는데 폭은 390(화면 전체)으로 잡혀 딱 여백만큼
 * 밖으로 나갔다. 그 안에 검색창과 상담 카드가 들어 있어 함께 밀렸다.
 *
 * 원인은 `width: min(720px, 100%)` 의 100% 다. 이 100% 는 부모의 안쪽 폭(여백을 뺀
 * 350)이어야 하는데 그 기기에서는 바깥 폭(390)으로 풀렸다. 맥·인앱 브라우저에서는
 * 같은 390px 에서도 350 으로 제대로 풀려 재현되지 않았다.
 *
 * width: auto 면 퍼센트를 계산할 일이 없다 — 그리드 칸에 맞춰 늘어날 뿐이라
 * 어느 브라우저에서도 여백 밖으로 나갈 수가 없다.
 * ──────────────────────────────────────────────────────────────── */
@media (max-width: 640px) {
  .simple-home .simple-home-choice > .home-hero-copy,
  .simple-home .simple-home-choice > div.home-hero-stage,
  .simple-home .home-hero-copy .home-hero-actions,
  .simple-home .home-hero-actions > .hero-search {
    width: auto;
    max-width: 100%;
    justify-self: stretch;
    align-self: stretch;
  }
}

/* ────────────────────────────────────────────────────────────────
 * 히어로의 그리드 칸이 내용을 따라 벌어지지 않게 못박는다.
 *
 * 사용자 아이폰 진단이 계속 같은 줄을 보여줬다:
 *   div.home-hero-copy [hero-shell가 자름] 390 →410 @2.4s
 * 왼쪽 20px 여백에서 시작하는데 폭이 390(화면 전체)이라 딱 여백만큼 밖으로 나갔다.
 *
 * 범인은 형제였다. .simple-home-choice 는 한 칸짜리 그리드인데, 그 안의
 * .home-reviews / .home-peek 만 min-width: auto 로 남아 있었고 그 속에는
 * width: 100vw(=390) 짜리 흐르는 띠가 들어 있다. "내용보다 작아지지 않겠다"는
 * 기본값 때문에 칸이 390 으로 벌어지고, 같은 칸을 쓰는 .home-hero-copy 와
 * 그 안의 검색창·상담 카드까지 통째로 390 이 되어 여백 밖으로 밀렸다.
 *
 * 크롬은 칸을 350 으로 유지해 재현되지 않았다 — 사파리만 내용 최소폭을 엄격히 지킨다.
 * minmax(0, 1fr) 은 칸이 부모를 넘지 못하게 하고, min-width: 0 은 각 항목이
 * 칸에 맞춰 줄어들게 한다. 둘 다 있어야 어느 브라우저에서도 성립한다.
 * ──────────────────────────────────────────────────────────────── */
@media (max-width: 640px) {
  .simple-home .simple-home-choice { grid-template-columns: minmax(0, 1fr); }
  .simple-home .simple-home-choice > * { min-width: 0; max-width: 100%; }
}

/* ────────────────────────────────────────────────────────────────
 * 킷 페이지 모바일판 — 손으로 짠 레이아웃 (components/brainwave-mobile.tsx)
 * 색은 킷 팔레트 그대로: 잉크 #161c2d / 포인트 #473bf0 / 가격 #68d585 / 바탕 #f4f7fa
 * ──────────────────────────────────────────────────────────────── */
/*
 * 글꼴은 데스크톱 킷과 같은 스택으로 — 안 그러면 같은 홈페이지의 제목이
 * PC(Urbanist+Pretendard)와 폰(앱 기본 글꼴)에서 다른 얼굴이 된다(사용자 지적).
 * 제목 자간도 킷처럼 음수로 죈다.
 */
.bwmob { width: 100%; background: #fff; color: #161c2d; font-family: var(--bw-latin), Pretendard, "Pretendard Variable", "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; font-size: 15px; line-height: 1.7; text-align: center; word-break: keep-all; }
/* 전역 letter-spacing 강제 규칙이 있어(킷 렌더도 --bw-ls 로 우회한다) 여기도 !important 로 잡는다 */
.bwmob :is(h1, h2, h3, strong) { letter-spacing: -0.02em !important; }
/*
 * 전역 :where(h1..h4){color:var(--text-strong)} 가 상속을 이겨, 어두운 구역과
 * 사진 위에서도 제목이 남색으로 찍혔다. 제목은 구역의 글색을 따르게 한다 —
 * 밝은 구역은 잉크, 어두운 구역·히어로는 흰색.
 */
.bwmob :is(h1, h2, h3) { color: inherit; }
.bwmob-sec { padding: 44px 20px; }
.bwmob-dark { background: #161c2d; color: #fff; }
.bwmob-soft { background: #f4f7fa; }
.bwmob-brand { margin: 0 0 26px; font-size: 22px; font-weight: 800; }
.bwmob-eyebrow { margin: 0 0 10px; color: #68d585; font-size: 13px; font-weight: 700; letter-spacing: .04em; }
.bwmob-h1 { margin: 0 0 22px; font-size: 27px; line-height: 1.35; font-weight: 800; }
.bwmob-h2 { margin: 0 0 10px; font-size: 21px; line-height: 1.4; font-weight: 800; }
.bwmob-sub { margin: 0 0 22px; color: inherit; opacity: .78; }
.bwmob-fine { margin: 12px 0 0; font-size: 12px; opacity: .6; }
.bwmob-btn { width: 100%; min-height: 52px; padding: 0 20px; border: 0; border-radius: 10px; background: #473bf0; color: #fff; font: inherit; font-size: 16px; font-weight: 700; cursor: pointer; }

/* 예약 묶음 */
.bwmob-book { display: grid; gap: 10px; }
.bwmob-field { display: flex; align-items: center; gap: 10px; min-height: 52px; padding: 0 16px; border-radius: 10px; background: #fff; color: #161c2d; font-weight: 600; text-align: left; }
.bwmob-field-ic { width: 18px; height: 18px; flex: none; }
.bwmob-caret { margin-left: auto; opacity: .45; font-size: 12px; }

/* 영상·사진 */
.bwmob-video { padding-top: 0; }
.bwmob-video-shot { position: relative; border-radius: 14px; overflow: hidden; }
.bwmob-cover { display: block; width: 100%; height: auto; }
.bwmob-play { position: absolute; inset: 0; display: grid; place-items: center; color: #fff; font-size: 20px; background: rgba(10,13,23,.25); }
.bwmob-video-label { margin: 12px 0 0; font-weight: 700; }
.bwmob-photo { display: block; width: 100%; height: auto; border-radius: 14px; margin: 0 0 18px; }

/* 숫자 셋 */
.bwmob-stats { display: grid; gap: 26px; }
.bwmob-stat strong { display: block; font-size: 40px; font-weight: 800; line-height: 1.1; }
.bwmob-stat p { margin: 6px 0 0; opacity: .75; }

/* 사진 카드 */
.bwmob-cards { display: grid; gap: 14px; }
.bwmob-card { border-radius: 14px; overflow: hidden; background: #fff; box-shadow: 0 8px 24px rgba(22,28,45,.08); text-align: left; }
.bwmob-card-img { display: block; width: 100%; height: 170px; object-fit: cover; }
.bwmob-card-body { display: flex; align-items: baseline; justify-content: space-between; padding: 13px 16px; }
.bwmob-card-body small { opacity: .6; }

/* 특징 목록 */
.bwmob-feats { display: grid; gap: 18px; text-align: left; }
.bwmob-feat { display: flex; gap: 14px; }
.bwmob-feat-ic { width: 26px; height: 26px; flex: none; margin-top: 3px; }
.bwmob-feat p { margin: 3px 0 0; opacity: .75; }

/* 체크 목록 */
.bwmob-checks { display: grid; gap: 18px; text-align: left; }
.bwmob-check { display: flex; gap: 12px; }
.bwmob-check-ic { flex: none; width: 24px; height: 24px; border-radius: 50%; background: #68d585; color: #0a0d17; display: grid; place-items: center; font-size: 13px; font-weight: 800; margin-top: 2px; }
.bwmob-check p { margin: 3px 0 0; opacity: .78; }

/* 구독 */
.bwmob-subscribe { display: grid; gap: 10px; }
.bwmob-subscribe input { min-height: 52px; padding: 0 16px; border: 1px solid #d8d8d8; border-radius: 10px; font: inherit; background: #fff; }

/* FAQ */
.bwmob-faq { text-align: left; display: grid; gap: 8px; }
.bwmob-faq details { border-bottom: 1px solid #eceff3; padding: 12px 2px; }
.bwmob-faq summary { font-weight: 700; cursor: pointer; list-style: none; display: flex; justify-content: space-between; gap: 10px; }
.bwmob-faq summary::after { content: "▾"; opacity: .4; }
.bwmob-faq details[open] summary::after { content: "▴"; }
.bwmob-faq p { margin: 10px 0 0; opacity: .75; }

/* 쇼핑몰 머리·히어로 */
.bwmob-shophead { display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; }
.bwmob-shophead strong { font-size: 19px; font-weight: 800; }
.bwmob-cart { position: relative; display: inline-grid; place-items: center; width: 40px; height: 40px; border-radius: 10px; background: #f4f7fa; }
.bwmob-cart-ic { width: 20px; height: 20px; }
.bwmob-cart i { position: absolute; top: -5px; right: -5px; min-width: 18px; height: 18px; border-radius: 999px; background: #473bf0; color: #fff; font: 700 11px/18px inherit; font-style: normal; }
.bwmob-shophero { position: relative; padding: 0; }
.bwmob-shophero .bwmob-cover { min-height: 300px; object-fit: cover; }
/*
 * 히어로 글은 사진의 세로 가운데에 둔다 — 모바일 히어로의 관례이고 사용자 요청.
 * 아래 깔때기 그라데이션 대신 사진 전체에 고른 스크림을 깔아 가운데 글이 읽히게 한다.
 */
.bwmob-shophero-txt { position: absolute; inset: 0; display: grid; place-content: center; padding: 26px 20px; background: rgba(10, 13, 23, .44); color: #fff; }
.bwmob-shophero-txt .bwmob-h1 { margin-bottom: 6px; font-size: 24px; }

/* 카테고리·상품 격자 */
.bwmob-cats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.bwmob-cat { display: grid; gap: 3px; padding: 14px 12px 12px; border-radius: 14px; background: #f4f7fa; }
.bwmob-cat-img { width: 100%; height: 88px; object-fit: contain; margin-bottom: 6px; }
.bwmob-cat small { opacity: .55; font-size: 12px; }
.bwmob-row { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 14px; }
.bwmob-row .bwmob-h2 { margin: 0; }
.bwmob-more { color: #473bf0; font-weight: 700; }
.bwmob-goods { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.bwmob-good { display: grid; gap: 2px; border-radius: 14px; background: #fff; padding: 12px 12px 14px; text-align: left; }
.bwmob-good-img { width: 100%; height: 120px; object-fit: contain; margin-bottom: 8px; }
.bwmob-good strong { font-size: 14px; }
.bwmob-price { margin: 0; color: #161c2d; font-weight: 800; display: flex; gap: 8px; align-items: baseline; }
.bwmob-was { color: #7d818d; font-weight: 500; text-decoration: line-through; font-size: 12px; }

/* 상담 페이지(0-290) — 히어로 버튼·단계·알림·후기 목록·신청 폼 */
.bwmob-shophero .bwmob-cover.bwmob-cover-tall { min-height: 420px; }
.bwmob-herosub { margin: 0 0 18px; font-size: 15px; line-height: 1.7; opacity: .85; }
.bwmob-shophero-txt .bwmob-btn { justify-self: center; min-width: 200px; }
.bwmob-steps { display: grid; gap: 18px; margin-top: 20px; text-align: left; }
.bwmob-step { display: flex; gap: 14px; align-items: flex-start; }
.bwmob-step-num { flex: none; width: 40px; height: 40px; border-radius: 999px; background: #473bf0; color: #fff; display: grid; place-items: center; font-weight: 800; font-size: 16px; }
.bwmob-step strong { display: block; margin-bottom: 3px; }
.bwmob-step p { margin: 0; opacity: .7; font-size: 14px; line-height: 1.65; }
.bwmob-noticewrap { padding-top: 24px; padding-bottom: 24px; }
.bwmob-notice { margin: 0; font-size: 14px; line-height: 1.7; }
.bwmob-badge { display: inline-block; margin-right: 8px; padding: 3px 10px; border-radius: 999px; background: #68d585; color: #0a0d17; font-weight: 700; font-size: 12px; }
.bwmob-quotes { display: grid; gap: 26px; }
.bwmob-quote footer { display: flex; align-items: center; gap: 8px; justify-content: center; }
/* 킷의 아바타 원본(imgOval*.png)이 투명 빈 PNG 라 배경 디스크를 깔아 둔다 */
.bwmob-quote-ava { width: 32px; height: 32px; border-radius: 999px; object-fit: cover; background: rgba(255, 255, 255, .16); }
.bwmob-form { display: grid; gap: 14px; padding: 20px 18px 22px; border-radius: 16px; background: #fff; box-shadow: 0 10px 30px rgba(22, 28, 45, .07); text-align: left; }
.bwmob-formfield { display: grid; gap: 6px; }
.bwmob-formfield small { font-weight: 700; font-size: 13px; color: #161c2d; }
.bwmob-formfield input { min-height: 48px; padding: 0 14px; border: 1px solid #d8d8d8; border-radius: 10px; font: inherit; background: #fff; }

/* 후기·CTA */
.bwmob-quote { margin: 0; }
.bwmob-quote p { margin: 0 0 12px; font-size: 16px; line-height: 1.75; }
.bwmob-quote footer { opacity: .7; font-size: 13px; }
.bwmob-cta .bwmob-h2 { margin-bottom: 18px; }

/* 푸터 */
.bwmob-footer { padding: 40px 20px 30px; background: #0a0d17; color: #fff; text-align: left; }
.bwmob-footer-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 22px 16px; }
.bwmob-footer-col strong { display: block; margin-bottom: 8px; font-size: 13px; opacity: .55; }
.bwmob-footer-col p { margin: 0 0 7px; font-size: 14px; }
.bwmob-footer-contact { margin: 24px 0 0; font-size: 14px; }
.bwmob-footer-contact strong { opacity: .55; font-weight: 600; margin-right: 6px; }
.bwmob-footer .bwmob-fine { opacity: .4; }

/* ── 히어로 타이포 손질 (2026-08-25, 사용자 요청) ──
 * 제목은 "사업, 오늘 하루면 충분합니다" 한 줄 — 크기를 줄이고(56→46) 몸통은
 * 600, "사업," 만 800 으로 굵기 대비를 준다. 눈썹은 파란 그라데이션이 흐른다.
 */
.simple-home .home-hero-copy h1 { font-size: 46px; font-weight: 600; letter-spacing: -0.03em; }
.simple-home .home-hero-copy h1 b { font-weight: 800; }
@media (max-width: 640px) {
  .simple-home .home-hero-copy h1 { font-size: 34px; line-height: 1.22; }
}
.simple-home .home-hero-copy > .section-label {
  background: linear-gradient(90deg, #3272db, #79b0ff, #4a3aff, #3272db);
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  animation: hero-label-flow 5s linear infinite;
}
@keyframes hero-label-flow { to { background-position: -300% 0; } }
@media (prefers-reduced-motion: reduce) {
  .simple-home .home-hero-copy > .section-label { animation: none; background: none; color: var(--blue); -webkit-text-fill-color: currentColor; }
}

/* 어드민 — 홈 문구 편집: 섹션 숨김 체크 목록 */
.admin-home-hide { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 18px; }
.admin-home-hide label { display: flex; align-items: center; gap: 9px; font-size: 14px; color: #1c1d21; cursor: pointer; }
@media (max-width: 640px) { .admin-home-hide { grid-template-columns: 1fr; } }

/* 계정 — 진행 중인 사업(플랜 목록), 플랜 대시보드와 같은 결 (2026-08-25) */
.account-plan-list { margin-top: 16px; display: grid; gap: 8px; }
.account-plan-list > button {
  min-height: 66px;
  padding: 12px 14px;
  border: 1px solid #ececf4;
  border-radius: 12px;
  background: #fff;
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto 16px;
  gap: 12px;
  align-items: center;
  text-align: left;
  cursor: pointer;
}
.account-plan-list > button:hover { border-color: var(--blue, #3272db); background: #fafbff; }
.account-plan-list > button > span { width: 40px; height: 40px; border-radius: 10px; display: grid; place-items: center; }
.account-plan-list > button > span svg { width: 19px; }
.account-plan-list > button strong { display: block; overflow: hidden; font-size: 14.5px; text-overflow: ellipsis; white-space: nowrap; }
.account-plan-list > button small { color: #5f5c7f; font-size: 12.5px; }
.account-plan-list > button > em { padding: 4px 10px; border-radius: 999px; font-size: 12px; font-style: normal; font-weight: 800; white-space: nowrap; }
.account-plan-list > button > svg { width: 15px; color: #8b95a1; }
.account-plan-all { margin-top: 6px; min-height: 42px; border-radius: 10px; background: #f5f5fa; color: #333d4b; display: flex; align-items: center; justify-content: center; gap: 6px; font-size: 13px; font-weight: 700; }
.account-plan-all:hover { background: #efeefb; }
.account-plan-all svg { width: 14px; }
@media (max-width: 640px) {
  .account-plan-list > button { grid-template-columns: 36px minmax(0, 1fr) 16px; }
  .account-plan-list > button > em { display: none; }
}

/* ══ 하단 개편 — TOP 50 레퍼런스(웹플로우 홈) 문법 ═══════════════════
 * 사용자가 준 레퍼런스에서 가져온 것: ① 초대형 좌측 정렬 디스플레이 헤드라인
 * ② 박스 대신 얇은 헤어라인 위의 4열 밸류 프롭 ③ 어두운 밴드로 리듬 주기
 * ④ 다열 메가 푸터. 히어로·데모·예시 홈페이지(위쪽)는 손대지 않는다.
 */

/* ── ① 섹션 헤드라인: 가운데 정렬 → 좌측 정렬 대형 디스플레이 ── */
.simple-home .home-section-heading,
.simple-home .home-deliverables-copy {
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
  align-items: start;
  justify-items: start;
  text-align: left;
  margin-bottom: 64px;
}
.simple-home .home-deliverables-copy { margin-bottom: 0; }
.simple-home .home-section-heading > span,
.simple-home .home-deliverables-copy > span { justify-self: start; }
.simple-home .home-section-heading h2,
.simple-home .home-deliverables-copy h2 { max-width: 880px; text-wrap: balance; }
.simple-home .home-deliverables-copy ul { justify-self: stretch; }
.simple-home .home-section-heading h2,
.simple-home .home-deliverables-copy h2,
.simple-home .home-evidence-intro h2,
.simple-home .home-price-copy h2,
.simple-home .home-faq h2,
.simple-home .home-stats h2 {
  font-size: clamp(36px, 4.8vw, 58px);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.032em;
}
.simple-home .home-section-heading p { max-width: 620px; font-size: 18px; }

/* ── ② 구성 요약: 흰 카드 4장 → 어두운 밴드 + 헤어라인 밸류 프롭 ── */
.simple-home .home-stats {
  padding: 110px var(--gutter) 120px;
  background: #08070f;
  justify-items: stretch;
  gap: 64px;
}
.simple-home .home-stats h2 {
  width: min(1264px, 100%);
  margin: 0 auto;
  color: #fff;
  text-align: left;
}
.simple-home .home-stats-cards { margin: 0 auto; gap: 46px 32px; }
.simple-home .home-stats-cards article {
  min-height: 0;
  padding: 24px 0 0;
  border-radius: 0;
  border-top: 1px solid rgba(255, 255, 255, .22);
  background: transparent;
  box-shadow: none;
  justify-items: start;
  text-align: left;
  gap: 10px;
  transition: border-color .25s ease;
}
.simple-home .home-stats-cards article:hover { border-top-color: rgba(255, 255, 255, .6); }
.simple-home .home-stats-cards strong { color: #fff; font-size: 42px; letter-spacing: -0.02em; }
.simple-home .home-stats-cards strong em { color: #9db9ff; font-size: 24px; }
.simple-home .home-stats-cards b { color: #fff; font-size: 17px; }
.simple-home .home-stats-cards p { color: #98a0b3; font-size: 15px; line-height: 1.7; }

/* ── ③ 진행 방식: 굵은 테두리 상자 → 얇은 헤어라인 열 ── */
.simple-home .home-method-flow { border-top-color: #e3e2f0; border-bottom: 0; }
.simple-home .home-method-flow article { min-height: 250px; border-left-color: #ececf4; }
.simple-home .home-method-flow article > svg { margin: 40px 0 14px; }
.simple-home .home-deliverables-copy ul { border-top-color: #dcdaee; }
.simple-home .home-faq { grid-template-columns: minmax(280px, 430px) 1fr; }

/* ── ④ 푸터: 한 줄 → 다열 메가 푸터(어두운 밴드) ── */
.simple-home .home-footer {
  padding: 92px var(--gutter) 44px;
  background: #08070f;
  color: #fff;
  justify-items: stretch;
}
.simple-home .home-footer .brand-logo { filter: brightness(0) invert(1); }
.simple-home .home-footer-main {
  width: min(1220px, 100%);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 56px;
  align-items: start;
}
.simple-home .home-footer-brand { display: grid; justify-items: start; gap: 16px; }
.simple-home .home-footer-brand p { max-width: 300px; margin: 0; color: #98a0b3; font-size: 15px; line-height: 1.7; }
.simple-home .home-footer-main nav { display: grid; justify-items: start; gap: 12px; }
.simple-home .home-footer-main nav strong { margin-bottom: 4px; color: #8b95a1; font-size: 13px; font-weight: 800; letter-spacing: .04em; }
.simple-home .home-footer-main nav a { color: #c3c9d4; font-size: 15px; line-height: 1.6; text-decoration: none; }
.simple-home .home-footer-main nav a:hover { color: #fff; }
.simple-home .home-footer-bottom {
  width: min(1220px, 100%);
  margin: 64px auto 0;
  padding-top: 26px;
  border-top: 1px solid rgba(255, 255, 255, .14);
  justify-items: start;
}
.simple-home .home-footer-bottom small { color: #8b95a1; text-align: left; }
.simple-home .home-footer-bottom small a { color: #b0b8c1; }
.simple-home .home-footer-notice {
  width: min(1220px, 100%);
  margin: 14px auto 0;
  justify-items: start;
  gap: 6px;
}
.simple-home .home-footer-notice p,
.simple-home .home-footer-notice small,
.simple-home .home-business-info { color: #77808f; text-align: left; }

@media (max-width: 900px) {
  .simple-home .home-footer-main { grid-template-columns: 1fr; gap: 36px; }
  .simple-home .home-stats-cards { grid-template-columns: 1fr 1fr; gap: 30px 22px; }
}
@media (max-width: 640px) {
  .simple-home .home-stats { padding: 72px var(--gutter) 80px; gap: 40px; }
  .simple-home .home-stats-cards { grid-template-columns: 1fr; }
  .simple-home .home-faq { grid-template-columns: 1fr; }
  /* 폰에서는 열 높이를 맞출 이웃이 없다 — 빈 여백만 남는 최소 높이를 푼다 */
  .simple-home .home-method-flow article { min-height: 0; }
  /*
   * 폰 제목 크기 — 36px 하한이면 짧은 화면 폭에서 제목이 네다섯 줄로
   * 세로로 길어진다. 폰에서는 두 줄 안에 들어오는 크기로 내린다.
   */
  .simple-home .home-section-heading h2,
  .simple-home .home-deliverables-copy h2,
  .simple-home .home-price-copy h2,
  .simple-home .home-faq h2,
  .simple-home .home-stats h2 { font-size: clamp(24px, 7vw, 30px); }
}

/* ── ⑤ 다크 카드 쇼케이스 — 레퍼런스의 Collaboration·SEO 카드 자리 ──
 * 실제 샘플 문서 화면을 축소해 담고, 커서가 단추를 누르면 본문 줄·손익
 * 막대가 채워지는 9초 루프. 전부 CSS. 움직임 줄이기에서는 완성된 상태로 멈춘다.
 */
.simple-home .home-stats-showcase {
  width: min(1264px, 100%);
  margin: 26px auto 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.simple-home .home-show-card {
  padding: 34px 34px 30px;
  border: 1px solid rgba(255, 255, 255, .09);
  border-radius: 14px;
  background: #12111c;
  display: grid;
  align-content: start;
  gap: 20px;
}
.simple-home .home-show-card > header { display: grid; gap: 10px; }
.simple-home .home-show-card > header strong { color: #fff; font-size: 22px; font-weight: 700; letter-spacing: -0.01em; }
.simple-home .home-show-card > header p { max-width: 480px; margin: 0; color: #98a0b3; font-size: 15px; line-height: 1.7; }
.simple-home .home-show-card > a {
  width: fit-content;
  color: #9db9ff;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
}
.simple-home .home-show-card > a svg { width: 15px; }
.simple-home .home-show-card > a:hover { color: #fff; }

.simple-home .home-show-stage { position: relative; }

/* 문서 카드 — 실제 문서 화면(흰 종이)을 축소한 목업 */
.simple-home .show-doc-page,
.simple-home .show-fin-panel {
  position: relative;
  min-height: 224px;
  padding: 18px 20px 60px;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 18px 44px rgba(0, 0, 0, .45);
}
.simple-home .show-doc-page > header,
.simple-home .show-fin-panel > header { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.simple-home .show-doc-page > header b,
.simple-home .show-fin-panel > header b { color: #0d0a2c; font-size: 13.5px; font-weight: 800; }
.simple-home .show-doc-page > header span,
.simple-home .show-fin-panel > header span { color: #8181a5; font-size: 11px; }
.simple-home .show-doc-page nav { margin: 12px 0 14px; display: flex; gap: 6px; }
.simple-home .show-doc-page nav i {
  padding: 4px 9px;
  border-radius: 999px;
  background: #f0f0f3;
  color: #55586a;
  font-size: 11px;
  font-style: normal;
  font-weight: 700;
  white-space: nowrap;
}
.simple-home .show-doc-page nav i.on { background: var(--blue, #3272db); color: #fff; }

/* 본문 줄 — 커서가 누르면 왼쪽부터 차오른다 */
.simple-home .show-doc-lines { display: grid; gap: 9px; }
.simple-home .show-doc-lines s {
  height: 9px;
  border-radius: 4px;
  background: #e3e2ee;
  text-decoration: none;
  transform-origin: left center;
  animation: showLine 9s ease-in-out infinite;
}
.simple-home .show-doc-lines s:nth-child(2) { animation-delay: .18s; }
.simple-home .show-doc-lines s:nth-child(3) { animation-delay: .36s; }
.simple-home .show-doc-lines s:nth-child(4) { animation-delay: .54s; }
.simple-home .show-doc-lines s:nth-child(5) { animation-delay: .72s; }
.simple-home .show-doc-lines s.short { width: 62%; }

/* 손익 패널 — 막대가 아래에서 차오른다. 숫자 라벨은 넣지 않는다(지어낸 수치 금지) */
.simple-home .show-fin-bars { height: 116px; margin-top: 18px; display: flex; align-items: flex-end; gap: 7px; }
.simple-home .show-fin-bars i {
  flex: 1;
  border-radius: 3px 3px 0 0;
  background: linear-gradient(180deg, #6f9bef, #3272db);
  transform-origin: bottom;
  animation: showBar 9s ease-in-out infinite;
}
.simple-home .show-fin-bars i:nth-child(1) { height: 16%; background: #d7d6e4; }
.simple-home .show-fin-bars i:nth-child(2) { height: 24%; background: #d7d6e4; animation-delay: .06s; }
.simple-home .show-fin-bars i:nth-child(3) { height: 20%; background: #d7d6e4; animation-delay: .12s; }
.simple-home .show-fin-bars i:nth-child(4) { height: 32%; animation-delay: .18s; }
.simple-home .show-fin-bars i:nth-child(5) { height: 40%; animation-delay: .24s; }
.simple-home .show-fin-bars i:nth-child(6) { height: 36%; animation-delay: .3s; }
.simple-home .show-fin-bars i:nth-child(7) { height: 50%; animation-delay: .36s; }
.simple-home .show-fin-bars i:nth-child(8) { height: 58%; animation-delay: .42s; }
.simple-home .show-fin-bars i:nth-child(9) { height: 54%; animation-delay: .48s; }
.simple-home .show-fin-bars i:nth-child(10) { height: 68%; animation-delay: .54s; }
.simple-home .show-fin-bars i:nth-child(11) { height: 80%; animation-delay: .6s; }
.simple-home .show-fin-bars i:nth-child(12) { height: 92%; animation-delay: .66s; }

/* 눌리는 단추 — 커서 클릭 타이밍(약 20%)에 살짝 눌린다 */
.simple-home .show-btn {
  position: absolute;
  right: 18px;
  bottom: 16px;
  min-height: 32px;
  padding: 0 14px;
  border-radius: 8px;
  background: var(--blue, #3272db);
  color: #fff;
  display: inline-flex;
  align-items: center;
  font-size: 12.5px;
  font-weight: 800;
  animation: showPress 9s ease-in-out infinite;
}

/* 커서 — 단추 위 자리에 서 있고, 루프마다 멀리서 다가와 누른다 */
.simple-home .show-cursor {
  position: absolute;
  right: 58px;
  bottom: 18px;
  width: 22px;
  height: 22px;
  z-index: 2;
  pointer-events: none;
  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, .4));
  animation: showCursor 9s cubic-bezier(.3, .6, .2, 1) infinite;
}
.simple-home .show-cursor svg { width: 100%; height: 100%; display: block; }
.simple-home .show-cursor::after {
  content: "";
  position: absolute;
  inset: -7px;
  border: 2px solid rgba(50, 114, 219, .8);
  border-radius: 50%;
  opacity: 0;
  animation: showRing 9s ease-out infinite;
}

@keyframes showCursor {
  0% { transform: translate(-230px, 74px); }
  15% { transform: translate(2px, 2px); }
  19% { transform: translate(2px, 2px) scale(.8); }
  23%, 80% { transform: translate(2px, 2px); }
  92%, 100% { transform: translate(-230px, 74px); }
}
@keyframes showRing {
  0%, 18% { opacity: 0; transform: scale(.4); }
  21% { opacity: .9; transform: scale(.9); }
  32%, 100% { opacity: 0; transform: scale(1.7); }
}
@keyframes showPress {
  0%, 18%, 24%, 100% { transform: none; filter: none; }
  20.5% { transform: scale(.93); filter: brightness(1.18); }
}
@keyframes showLine {
  0%, 22% { transform: scaleX(0); opacity: .35; }
  34%, 86% { transform: none; opacity: 1; }
  95%, 100% { transform: scaleX(0); opacity: .35; }
}
@keyframes showBar {
  0%, 22% { transform: scaleY(.05); }
  42%, 86% { transform: none; }
  95%, 100% { transform: scaleY(.05); }
}

@media (max-width: 900px) {
  .simple-home .home-stats-showcase { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .simple-home .home-show-card { padding: 24px 20px 22px; }
  .simple-home .show-doc-page nav i:last-child { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .simple-home .show-cursor { display: none; }
  .simple-home .show-doc-lines s,
  .simple-home .show-fin-bars i,
  .simple-home .show-btn { animation: none; }
}

/* ── ⑥ 숫자 4칸 → 글로우 피처 카드(SEO 도구 레퍼런스) ───────────────
 * 헤어라인 줄이던 것을, 위쪽에 격자·보랏빛 글로우 비주얼을 얹은 다크
 * 카드로 바꾼다. 항목마다 비주얼이 다르다 — 문서 묶음 / 샘플 표지 /
 * 무료 구간 잠금 / 파일 칩. 텍스트(숫자·이름·설명)는 그대로다.
 */
.simple-home .home-stats-cards { gap: 24px; }
.simple-home .home-stats-cards article {
  padding: 10px 10px 24px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 16px;
  background: linear-gradient(180deg, #16132a 0%, #0d0b16 60%);
  gap: 6px;
  overflow: hidden;
  transition: transform .3s cubic-bezier(.22, .61, .21, 1), border-color .3s ease;
}
.simple-home .home-stats-cards article:hover {
  transform: translateY(-3px);
  border-top-color: rgba(255, 255, 255, .22);
  border-color: rgba(255, 255, 255, .22);
}
.simple-home .home-stats-cards article > strong,
.simple-home .home-stats-cards article > b,
.simple-home .home-stats-cards article > p { padding: 0 16px; }
.simple-home .home-stats-cards article > strong { margin-top: 14px; font-size: 34px; }
.simple-home .home-stats-cards strong em { font-size: 20px; }
.simple-home .home-stats-cards b { font-size: 16px; }
.simple-home .home-stats-cards p { font-size: 14px; }

/* 비주얼 무대 — 은은한 격자 + 가운데 위 보랏빛 글로우 */
.simple-home .stat-viz {
  position: relative;
  display: grid;
  place-items: center;
  /* 카드의 justify-items:start 가 무대를 내용 폭으로 줄인다 — 가로로 꽉 채운다 */
  width: 100%;
  justify-self: stretch;
  height: 128px;
  border-radius: 10px;
  background:
    linear-gradient(rgba(255, 255, 255, .045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .045) 1px, transparent 1px),
    radial-gradient(70% 90% at 50% 0%, rgba(116, 84, 255, .28), transparent 70%),
    #0b0913;
  background-size: 26px 26px, 26px 26px, 100% 100%, 100% 100%;
  overflow: hidden;
  transition: box-shadow .3s ease;
}
.simple-home .home-stats-cards article:hover .stat-viz {
  box-shadow: inset 0 0 60px rgba(116, 84, 255, .22);
}

/* ① 문서 묶음 — 부채꼴로 겹친 종이 세 장 */
.simple-home .viz-pages { position: relative; width: 54px; height: 72px; }
.simple-home .viz-pages i {
  position: absolute;
  inset: 0;
  border-radius: 5px;
  background:
    repeating-linear-gradient(#fff 0 26px, #d9d8e6 26px 29px, #fff 29px 40px) ;
  background-color: #fff;
  box-shadow: 0 8px 24px rgba(0, 0, 0, .5);
}
.simple-home .viz-pages i:nth-child(1) { transform: rotate(-10deg) translateX(-16px); opacity: .45; }
.simple-home .viz-pages i:nth-child(2) { transform: rotate(9deg) translateX(16px); opacity: .65; }
.simple-home .viz-pages i:nth-child(3) {
  background: linear-gradient(180deg, #fff 0 18px, transparent 18px),
    repeating-linear-gradient(transparent 0 24px, #e3e2ee 24px 30px);
  background-color: #fff;
}

/* ② 샘플 표지 세 장 — 실제 샘플 이름표 */
.simple-home .viz-samples { display: flex; gap: 8px; }
.simple-home .viz-samples i {
  width: 58px;
  padding: 26px 6px 8px;
  border: 1px solid rgba(255, 255, 255, .14);
  border-radius: 6px;
  background: linear-gradient(180deg, rgba(116, 84, 255, .35) 0 18px, rgba(255, 255, 255, .06) 18px);
  color: #cfd4e2;
  font-size: 9.5px;
  font-style: normal;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
}
.simple-home .viz-samples i:nth-child(2) { transform: translateY(-8px); border-color: rgba(255, 255, 255, .28); background: linear-gradient(180deg, rgba(50, 114, 219, .5) 0 18px, rgba(255, 255, 255, .1) 18px); color: #fff; }

/* ③ 무료 구간 — 앞 두 줄은 열려 있고 세 번째부터 잠금 */
.simple-home .viz-free { width: 64%; display: grid; gap: 9px; }
.simple-home .viz-free i { position: relative; height: 15px; border-radius: 999px; background: rgba(255, 255, 255, .1); }
.simple-home .viz-free i::before {
  content: "✓";
  position: absolute;
  left: -24px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #22b573;
  color: #fff;
  font-size: 10px;
  line-height: 16px;
  text-align: center;
}
.simple-home .viz-free i.on { background: linear-gradient(90deg, rgba(50, 114, 219, .75), rgba(116, 84, 255, .55)); }
.simple-home .viz-free i.lock { opacity: .5; }
.simple-home .viz-free i.lock::before { content: "🔒"; background: transparent; font-size: 11px; }

/* ④ 파일 칩 — 내려받는 세 형식 */
.simple-home .viz-files { display: flex; gap: 8px; }
.simple-home .viz-files b {
  min-width: 46px;
  padding: 9px 8px;
  border-radius: 8px;
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  text-align: center;
  box-shadow: 0 8px 22px rgba(0, 0, 0, .45);
}
.simple-home .viz-files .pdf { background: #d64545; }
.simple-home .viz-files .docx { background: #3272db; }
.simple-home .viz-files .ppt { background: #d97b34; transform: translateY(6px); }
.simple-home .viz-files .pdf { transform: translateY(6px); }

@media (max-width: 640px) {
  .simple-home .stat-viz { height: 112px; }
}

/* ── ⑦ 근거 섹션 → 어두운 밴드 + 텍스트 매트릭스(Hardened security 레퍼런스) ──
 * 배경에 '검증 안 된 수치'(숫자는 ###로 가림)가 흐르고 깜빡이며, 일부는
 * 줄이 그어진다. 가운데는 글로우 배지 + 헤드라인 + 판정 칩 세 개.
 */
.simple-home .evidence-dark {
  position: relative;
  /* 베이스 .home-evidence 의 2열 그리드·폭 제한을 푼다 — 여기는 풀블리드 밴드다 */
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 140px var(--gutter) 120px;
  background: #08070f;
  overflow: hidden;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  align-items: start;
  gap: 64px;
}

/* 배경 매트릭스 — 여섯 줄이 서로 다른 속도로 좌우로 흐른다 */
.simple-home .evidence-matrix {
  position: absolute;
  inset: 40px 0 auto;
  display: grid;
  gap: 34px;
  pointer-events: none;
  /* 가운데는 글이 읽혀야 한다 — 중심으로 갈수록 어둡게 가라앉힌다 */
  mask-image: radial-gradient(75% 75% at 50% 46%, transparent 0 26%, #000 78%);
}
.simple-home .ev-row {
  display: flex;
  gap: 38px;
  justify-content: center;
  white-space: nowrap;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 13px;
  letter-spacing: .02em;
  animation: evDrift 16s ease-in-out infinite alternate;
}
.simple-home .ev-row-1 { animation-duration: 21s; animation-direction: alternate-reverse; }
.simple-home .ev-row-2 { animation-duration: 26s; }
.simple-home .ev-row span { animation: evFlicker 6s ease-in-out infinite; }
.simple-home .ev-row span:nth-child(2n) { animation-delay: 1.4s; }
.simple-home .ev-row span:nth-child(3n) { animation-delay: 2.9s; animation-duration: 8s; }
.simple-home .ev-row span:nth-child(5n) { animation-delay: 4.2s; }
.simple-home .ev-row .dim { color: rgba(151, 158, 179, .4); }
.simple-home .ev-row .glow { color: #a08dff; text-shadow: 0 0 14px rgba(124, 92, 255, .8); }
.simple-home .ev-row .cut { color: rgba(151, 158, 179, .5); text-decoration: line-through; text-decoration-color: rgba(214, 69, 69, .85); text-decoration-thickness: 1.5px; }

@keyframes evDrift { from { transform: translateX(-30px); } to { transform: translateX(30px); } }
@keyframes evFlicker { 0%, 100% { opacity: .5; } 50% { opacity: 1; } }

/* 가운데 무대 */
.simple-home .evidence-center {
  position: relative;
  z-index: 1;
  /*
   * 로테이터 문장이 absolute 라 부모 폭에 기여하지 않는다 — 내용 맞춤으로
   * 두면 엠블럼 폭(150px)까지 쪼그라들어 글이 넘쳤다. 폭을 직접 준다.
   */
  width: min(880px, 100%);
  display: grid;
  justify-items: center;
  gap: 22px;
  text-align: center;
}
.simple-home .evidence-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  border: 1px solid rgba(160, 141, 255, .4);
  border-radius: 999px;
  background: rgba(124, 92, 255, .12);
  color: #cabfff;
  font-size: 13px;
  font-weight: 800;
  box-shadow: 0 0 34px rgba(124, 92, 255, .35);
}
.simple-home .evidence-badge svg { width: 15px; }
.simple-home .evidence-dark h2 {
  margin: 0;
  color: #fff;
  /* nowrap 두 줄이 좁은 화면에서도 들어가게 — 아래로 길어지는 대신 작아진다 */
  font-size: clamp(24px, 4.9vw, 54px);
  font-weight: 700;
  line-height: 1.16;
  letter-spacing: -0.03em;
  text-shadow: 0 0 60px rgba(124, 92, 255, .35);
}
.simple-home .evidence-center > p { max-width: 560px; margin: 0; color: #98a0b3; font-size: 17px; line-height: 1.75; }

/* 판정 칩 — 셋 중 무엇으로 남는지. 차례로 숨 쉬듯 밝아진다 */
.simple-home .evidence-verdicts { margin-top: 6px; display: flex; gap: 10px; }
.simple-home .evidence-verdicts i {
  padding: 8px 16px;
  border: 1px solid rgba(255, 255, 255, .16);
  border-radius: 999px;
  color: #c3c9d4;
  font-size: 13.5px;
  font-style: normal;
  font-weight: 800;
  animation: evVerdict 5.4s ease-in-out infinite;
}
.simple-home .evidence-verdicts .ok { border-color: rgba(34, 181, 115, .5); color: #6fe0ae; }
.simple-home .evidence-verdicts .assume { border-color: rgba(224, 161, 0, .5); color: #ffd37a; animation-delay: 1.8s; }
.simple-home .evidence-verdicts .check { border-color: rgba(214, 69, 69, .5); color: #ff9d8f; animation-delay: 3.6s; }
@keyframes evVerdict {
  0%, 100% { transform: none; box-shadow: none; }
  18% { transform: translateY(-2px); box-shadow: 0 0 22px rgba(124, 92, 255, .3); }
  36% { transform: none; box-shadow: none; }
}
.simple-home .evidence-principle { margin: 0; color: #77808f; font-size: 14px; }

/* 4단계 표 — 어두운 유리 카드 4열로 */
.simple-home .evidence-dark .home-evidence-table {
  position: relative;
  z-index: 1;
  width: min(1264px, 100%);
  border-top: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.simple-home .evidence-dark .home-evidence-table > div {
  min-height: 0;
  padding: 20px;
  border: 1px solid rgba(255, 255, 255, .09);
  border-bottom: 1px solid rgba(255, 255, 255, .09);
  border-radius: 12px;
  background: rgba(255, 255, 255, .03);
  grid-template-columns: 26px 1fr;
  grid-template-rows: auto auto;
  align-items: start;
  gap: 6px 10px;
  transition: border-color .25s ease, transform .25s var(--pl-ease, ease);
}
.simple-home .evidence-dark .home-evidence-table > div:hover { border-color: rgba(255, 255, 255, .22); transform: translateY(-2px); }
.simple-home .evidence-dark .home-evidence-table em { color: #8b95a1; }
.simple-home .evidence-dark .home-evidence-table strong { color: #fff; font-size: 15.5px; }
.simple-home .evidence-dark .home-evidence-table small { color: #98a0b3; }
.simple-home .evidence-dark .home-evidence-table b {
  grid-column: 2;
  justify-self: start;
  border-color: rgba(157, 185, 255, .4);
  color: #9db9ff;
  background: rgba(50, 114, 219, .12);
}
.simple-home .evidence-dark .home-evidence-table > div:nth-child(3) b { border-color: rgba(224, 161, 0, .45); color: #ffd37a; background: rgba(224, 161, 0, .1); }

@media (max-width: 900px) {
  .simple-home .evidence-dark .home-evidence-table { grid-template-columns: 1fr 1fr; }
  .simple-home .ev-row { gap: 26px; font-size: 12px; }
}
@media (max-width: 640px) {
  .simple-home .evidence-dark { padding: 90px var(--gutter) 80px; gap: 44px; }
  .simple-home .evidence-dark .home-evidence-table { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  .simple-home .ev-row, .simple-home .ev-row span, .simple-home .evidence-verdicts i { animation: none; }
}

/* ── ⑦-2 레퍼런스 그대로: 글로우 엠블럼 + 교체되는 헤드라인 ── */
.simple-home .evidence-emblem {
  position: relative;
  width: 150px;
  height: 150px;
  display: grid;
  place-items: center;
}
.simple-home .emblem-core {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background: radial-gradient(circle at 35% 30%, #8d6bff, #4a2ee0 70%);
  box-shadow: 0 0 40px rgba(124, 92, 255, .8), 0 0 130px rgba(124, 92, 255, .45);
}
.simple-home .emblem-core svg { width: 30px; height: 30px; }
.simple-home .evidence-emblem .ring {
  position: absolute;
  border: 1px solid rgba(160, 141, 255, .28);
  border-radius: 50%;
  animation: evRing 6s ease-in-out infinite;
}
.simple-home .evidence-emblem .r1 { inset: 26px; }
.simple-home .evidence-emblem .r2 { inset: 8px; opacity: .65; animation-delay: 1.2s; }
.simple-home .evidence-emblem .r3 { inset: -14px; opacity: .35; animation-delay: 2.4s; }
@keyframes evRing { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.07); } }

/*
 * 헤드라인 로테이터 — 근거 원칙 네 문장이 4초씩 교체된다.
 * 문장들이 같은 자리에 겹쳐 서고(absolute), 아래에서 떠올라 위로 사라진다.
 * 높이는 두 줄 기준으로 고정해 아래 내용이 출렁이지 않게 한다.
 */
.simple-home .evidence-rotator {
  position: relative;
  width: 100%;
  min-height: 2.45em;
}
.simple-home .evidence-rotator span {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  /*
   * 줄바꿈은 문장에 넣어 둔 <br> 한 번뿐이다 — 자동 줄바꿈이 끼어들면
   * 좁은 화면에서 서너 줄로 세로로 길어진다. 대신 글자 크기가 화면 폭을
   * 따라 줄어들어(아래 h2 clamp) 두 줄이 항상 들어간다.
   */
  white-space: nowrap;
  opacity: 0;
  animation: evSwap 16s ease-in-out infinite;
}
.simple-home .evidence-rotator span:nth-child(2) { animation-delay: 4s; }
.simple-home .evidence-rotator span:nth-child(3) { animation-delay: 8s; }
.simple-home .evidence-rotator span:nth-child(4) { animation-delay: 12s; }
@keyframes evSwap {
  0% { opacity: 0; transform: translateY(18px); filter: blur(7px); }
  3%, 23% { opacity: 1; transform: none; filter: none; }
  26.5%, 100% { opacity: 0; transform: translateY(-16px); filter: blur(7px); }
}

@media (prefers-reduced-motion: reduce) {
  .simple-home .evidence-emblem .ring { animation: none; }
  .simple-home .evidence-rotator span { animation: none; }
  .simple-home .evidence-rotator span:first-child { opacity: 1; }
  .simple-home .evidence-rotator span:not(:first-child) { display: none; }
}

/* ── 구글 로그인 버튼 자리(/account) ── */
.account-google { display: grid; gap: 12px; margin-bottom: 4px; }
.account-google-btn { min-height: 44px; display: grid; justify-items: stretch; }
.account-google-btn > div { width: 100% !important; }
.account-google > small { color: #8181a5; font-size: 12px; line-height: 1.6; }
.account-google > small a { color: #55586a; text-decoration: underline; }
.account-divider { display: flex; align-items: center; gap: 12px; }
.account-divider i { flex: 1; height: 1px; background: #e6e6ef; }
.account-divider span { color: #8181a5; font-size: 12.5px; font-weight: 700; white-space: nowrap; }

/* ── /account 로그인 카드 현대화 ──────────────────────────────────
 * 각진 8px 카드·검정 버튼이던 것을 부드러운 20px 카드, 파랑 주 버튼,
 * 옅은 입력칸으로 바꾼다. 구글 버튼은 폼 아래 '또는' 선 밑 — 익숙한 자리다.
 */
.account-page { background: #f6f5ff; }
.account-auth-shell { width: min(430px, calc(100% - 32px)); }
.account-auth-shell > form {
  padding: 38px 32px 30px;
  border: 1px solid #ececf4;
  border-radius: 20px;
  box-shadow: 0 24px 70px rgba(13, 10, 44, .1);
  gap: 17px;
}
.account-auth-shell > form > header { padding-bottom: 4px; border-bottom: 0; gap: 8px; }
.account-auth-shell > form > header strong { font-size: 26px; letter-spacing: -0.03em; }
.account-auth-shell > form > header p { font-size: 14px; color: #8181a5; }
.account-auth-shell > form > label > span { font-size: 13px; color: #55586a; }
.account-auth-shell > form > label > div {
  height: 50px;
  padding: 0 14px;
  border: 1px solid #e2e2ee;
  border-radius: 12px;
  background: #fafaff;
  transition: border-color .15s ease, box-shadow .15s ease, background .15s ease;
}
.account-auth-shell > form > label > div:focus-within {
  border-color: var(--blue, #3272db);
  background: #fff;
  box-shadow: 0 0 0 4px rgba(50, 114, 219, .1);
}
.account-auth-shell input { background: transparent; font-size: 15px; }
.account-submit {
  min-height: 52px;
  border-radius: 12px;
  background: var(--blue, #3272db);
  font-size: 15px;
  transition: background .15s ease, transform .12s ease, box-shadow .2s ease;
}
.account-submit:not(:disabled):hover { background: #2a63c2; box-shadow: 0 10px 24px rgba(50, 114, 219, .3); transform: translateY(-1px); }
.account-submit:not(:disabled):active { transform: none; }
.account-consents { border-radius: 12px; }
.account-form-message, .account-message { border-radius: 10px; }
.account-auth-shell form > footer { justify-content: center; padding-top: 2px; }
.account-auth-shell form > footer span { color: #8181a5; font-size: 13.5px; }
.account-auth-shell form > footer button { color: var(--blue, #3272db); font-weight: 800; font-size: 13.5px; }

/* 구글 버튼 줄 — 가운데 정렬, 위에 '또는' 선 */
.account-google { margin: 2px 0 0; gap: 14px; }
.account-google-btn { justify-items: center; }
.account-google-btn > div { width: auto !important; }
.account-divider { margin-top: 2px; }
.account-google > small { text-align: center; }

/* ── 소셜 로그인 두 개 나란히 — 구글(GIS) + 카카오 ── */
.account-social-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  align-items: center;
}
.account-social-row .account-google-btn { justify-items: stretch; min-height: 40px; }
.account-kakao-btn {
  height: 40px;
  padding: 0 12px;
  border: 0;
  /* 카카오 버튼 규정색 — 노랑 바탕에 검정 글·심볼 */
  border-radius: 20px; /* GIS pill(높이 40)과 같은 둥글기 */
  background: #fee500;
  color: rgba(0, 0, 0, .85);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  transition: filter .15s ease;
}
.account-kakao-btn:hover { filter: brightness(.96); }
.account-kakao-btn:disabled { opacity: .5; cursor: not-allowed; }
.account-kakao-btn svg { width: 17px; height: 17px; fill: rgba(0, 0, 0, .9); flex: none; }
@media (max-width: 380px) {
  .account-social-row { grid-template-columns: 1fr; }
}

/* ── /account — 월렛 앱 레퍼런스 배치 ─────────────────────────────
 * 가운데 인사말 → '간편하게 계속하기' 소셜 두 알약 → 라벨 없는 채움
 * 입력칸(자리말+아이콘) → 가운데 알약 주 버튼 → 작은 안내 한 줄.
 */
.account-auth-shell > form { gap: 14px; padding: 40px 30px 30px; }
.account-auth-shell > form > header { justify-items: center; text-align: center; gap: 6px; padding-bottom: 6px; }
.account-auth-shell > form > header strong { font-size: 23px; line-height: 1.4; letter-spacing: -0.02em; color: #221d4e; }
.account-social-caption { display: block; color: #9a98b5; font-size: 12px; font-weight: 700; text-align: center; }
.account-google { gap: 12px; margin: 0 0 6px; }
.account-social-row { max-width: 360px; width: 100%; margin: 0 auto; }

/* 라벨은 낭독기에만 — 눈에는 자리말(placeholder)로 보인다 */
.account-auth-shell > form > label { gap: 0; }
.account-auth-shell > form > label > span {
  position: absolute;
  width: 1px; height: 1px;
  margin: -1px; padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
.account-auth-shell > form > label > div {
  height: 52px;
  padding: 0 16px;
  border: 1.5px solid transparent;
  border-radius: 14px;
  background: #f1f1f6;
}
.account-auth-shell > form > label > div:focus-within { border-color: var(--blue, #3272db); background: #fff; }
.account-auth-shell input::placeholder { color: #9a98b5; }
.account-auth-shell > form > label svg { color: #9a98b5; }
.account-hint { margin: 6px 2px 0; color: #9a98b5; font-size: 12px; }

.account-submit {
  justify-self: center;
  width: auto;
  min-width: 230px;
  min-height: 52px;
  margin-top: 4px;
  padding: 0 46px;
  border-radius: 999px;
}
.account-optionrow { padding: 0 2px; }
.account-auth-shell form > footer span, .account-auth-shell form > footer > button { font-size: 13px; color: #9a98b5; }
.account-auth-shell form > footer span button { font-size: 13px; }

/* ── 소셜 버튼 한 벌로 + 입력칸 흰 배경 제거 ─────────────────────
 * 구글 공식 버튼(GIS)은 생김새를 바꿀 수 없어 카카오와 어긋났다.
 * 우리가 그린 버튼을 보이게 두고, 공식 버튼은 그 위에 투명하게 얹는다 —
 * 클릭은 공식 버튼이 받으므로 로그인 동작은 그대로다.
 */
.account-google-btn,
.account-kakao-btn {
  position: relative;
  height: 48px;
  min-height: 48px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.account-google-btn {
  background: #fff;
  border: 1.5px solid #e2e2ee;
  overflow: hidden;
  transition: border-color .15s ease;
}
.account-google-btn:hover { border-color: #c9c8dd; }
.account-social-visual {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #3d3a52;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  pointer-events: none;
}
.account-social-visual svg { width: 17px; height: 17px; flex: none; }
/* 공식 버튼 — 보이지 않지만 클릭·포커스는 전부 받는다 */
.account-google-real {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.0001;
}
.account-kakao-btn {
  border: 0;
  border-radius: 14px;
  padding: 0;
  background: #fee500;
  color: rgba(0, 0, 0, .85);
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
}

/*
 * 입력칸 안 흰 상자 — 전역 어딘가의 입력 배경이 케스케이드에서 이겨
 * 회색 칸 안에 흰 네모가 떠 있었다. 여기서는 칸(label>div)이 배경을
 * 그리고 입력은 늘 투명해야 한다.
 */
.account-auth-shell > form label input { background: transparent !important; }

/*
 * 카카오 로고 되살리기.
 * 전역 '버튼은 아이콘 대신 텍스트' 규칙(button:not(.plan-ui *) svg 숨김,
 * !important)이 이 로고까지 지웠다 — 구글은 버튼이 아닌 span 안이라 살았고
 * 카카오만 글자만 남아 짝이 안 맞았다. 같은 힘(중요·더 높은 특이도)으로 되살린다.
 */
button.account-kakao-btn svg { display: inline-block !important; }

/* ── ⑥-2 피처 카드 속 레이어 애니메이션 ─────────────────────────
 * 정지화면이던 비주얼에 느린 숨을 넣는다: 격자가 흐르고 글로우가 숨쉬며,
 * 레이어(종이·표지·칩)가 둥실거린다. 전부 6~9초의 미세한 루프 — 시선을
 * 뺏지 않고 살아 있음만 전한다. 호버 시 레이어가 펼쳐진다.
 */

/* 무대: 격자 대각 흐름 + 글로우 숨쉼 */
.simple-home .stat-viz { animation: vizGrid 9s linear infinite; }
.simple-home .stat-viz::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(60% 80% at 50% 0%, rgba(116, 84, 255, .22), transparent 70%);
  animation: vizGlow 5s ease-in-out infinite;
  pointer-events: none;
}
@keyframes vizGrid { to { background-position: 26px 26px, 26px 26px, 0 0, 0 0; } }
@keyframes vizGlow { 0%, 100% { opacity: .35; } 50% { opacity: 1; } }

/* ① 문서 묶음 — 전체가 둥실, 호버에 부채가 펼쳐진다 */
.simple-home .viz-pages { animation: vizBob 6s ease-in-out infinite; }
.simple-home .viz-pages i { transition: transform .45s cubic-bezier(.22, .61, .21, 1), opacity .3s ease; }
.simple-home .home-stats-cards article:hover .viz-pages i:nth-child(1) { transform: rotate(-17deg) translateX(-26px); opacity: .6; }
.simple-home .home-stats-cards article:hover .viz-pages i:nth-child(2) { transform: rotate(15deg) translateX(26px); opacity: .8; }

/* ② 샘플 표지 — 셋이 번갈아 떠오르고, 호버에 양옆으로 벌어진다 */
.simple-home .viz-samples i { animation: vizBob 5s ease-in-out infinite; transition: transform .45s cubic-bezier(.22, .61, .21, 1); }
.simple-home .viz-samples i:nth-child(1) { animation-delay: .4s; }
.simple-home .viz-samples i:nth-child(2) { animation: vizBobMid 5s ease-in-out infinite; }
.simple-home .viz-samples i:nth-child(3) { animation-delay: 1.1s; }
.simple-home .home-stats-cards article:hover .viz-samples i:nth-child(1) { transform: translateX(-7px) rotate(-4deg); }
.simple-home .home-stats-cards article:hover .viz-samples i:nth-child(3) { transform: translateX(7px) rotate(4deg); }

/* ③ 무료 구간 — 열린 줄엔 빛이 지나가고, 체크가 맥동, 잠금은 이따금 갸웃 */
.simple-home .viz-free i.on { position: relative; overflow: hidden; }
.simple-home .viz-free i.on::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg, transparent 30%, rgba(255, 255, 255, .45) 50%, transparent 70%);
  transform: translateX(-110%);
  animation: vizSheen 4.2s ease-in-out infinite;
}
.simple-home .viz-free i:nth-child(2).on::after { animation-delay: .5s; }
.simple-home .viz-free i.on::before { animation: vizCheck 4.2s ease-in-out infinite; }
.simple-home .viz-free i:nth-child(2).on::before { animation-delay: .5s; }
.simple-home .viz-free i.lock::before { animation: vizLock 6s ease-in-out infinite; }
@keyframes vizSheen { 0%, 55% { transform: translateX(-110%); } 80%, 100% { transform: translateX(110%); } }
@keyframes vizCheck { 0%, 60%, 100% { transform: translateY(-50%) scale(1); } 70% { transform: translateY(-50%) scale(1.25); } }
@keyframes vizLock { 0%, 86%, 100% { transform: translateY(-50%) rotate(0); } 90% { transform: translateY(-50%) rotate(-12deg); } 94% { transform: translateY(-50%) rotate(10deg); } }

/* ④ 파일 칩 — 서로 어긋나게 부유, 호버에 줄을 맞춘다 */
.simple-home .viz-files b { transition: transform .4s cubic-bezier(.22, .61, .21, 1); }
.simple-home .viz-files .pdf { animation: vizBobLow 5.4s ease-in-out infinite; }
.simple-home .viz-files .docx { animation: vizBob 5.4s ease-in-out infinite .9s; }
.simple-home .viz-files .ppt { animation: vizBobLow 5.4s ease-in-out infinite 1.8s; }
.simple-home .home-stats-cards article:hover .viz-files b { animation-play-state: paused; transform: translateY(0) scale(1.06); }

@keyframes vizBob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
@keyframes vizBobMid { 0%, 100% { transform: translateY(-8px); } 50% { transform: translateY(-15px); } }
@keyframes vizBobLow { 0%, 100% { transform: translateY(6px); } 50% { transform: translateY(0); } }

@media (prefers-reduced-motion: reduce) {
  .simple-home .stat-viz,
  .simple-home .stat-viz::after,
  .simple-home .viz-pages,
  .simple-home .viz-samples i,
  .simple-home .viz-free i.on::after,
  .simple-home .viz-free i.on::before,
  .simple-home .viz-free i.lock::before,
  .simple-home .viz-files b { animation: none; }
}

/* ── FAQ 태블릿 정리 ─────────────────────────────────────────────
 * 위의 2열 규칙(minmax(280,430) 1fr)이 폭 제한 없이 걸려, 태블릿에서
 * 질문 칸이 최소 폭까지 쪼그라들어 낱말이 한두 글자씩 꺾였다(사용자 보고).
 * 넓은 화면에서만 2열을 쓰고, 그 아래(≤1160)는 제목 아래 질문이 오는
 * 세로 스택으로 되돌린다.
 */
@media (max-width: 1160px) {
  .simple-home .home-faq { grid-template-columns: 1fr; gap: 36px; }
  .simple-home .home-faq > div:first-child { max-width: 560px; }
}

/* ── 하단 텍스트 섹션 헤딩 정렬 통일 ─────────────────────────────
 * '문서 유형'은 좌측인데 '이용 안내'·FAQ 는 가운데라 섞여 있었다(사용자
 * 지적). 다크 매트릭스 밴드만 레퍼런스대로 중앙을 유지하고, 나머지 텍스트
 * 섹션 헤딩은 전부 좌측 정렬로 맞춘다.
 */
.simple-home .home-price-copy,
.simple-home .home-faq > div:first-child {
  justify-items: start;
  justify-self: start;
  text-align: left;
}
.simple-home .home-price-copy > div { justify-content: flex-start; }
.simple-home .home-faq > div:first-child { max-width: 880px; }
.simple-home .home-faq > div:last-child { justify-self: start; width: min(812px, 100%); }

/* ── 내 사업 홈페이지 패널 다듬기 ─────────────────────────────────
 * ① 미리보기를 브라우저 목업(신호등 점·주소창) 안에 — 손님 브라우저에서
 *   열리는 화면임이 한눈에 읽힌다.
 * ② 머리줄·접이식 요약의 글자 침범 수리 — 좁은 폭에서 주소가 버튼 밑으로
 *   파고들고, 배지가 제목에 붙어 있었다.
 * ③ 큰 버튼·접이식 카드의 손맛(호버) 정돈.
 */
.hk-mock { border: 1px solid #e3e2ee; border-radius: 16px; overflow: hidden; box-shadow: 0 18px 48px rgba(13, 10, 44, .1); }
.hk-mock-bar {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 10px 14px;
  background: #f3f2f9;
  border-bottom: 1px solid #e7e6f0;
}
.hk-dot { width: 11px; height: 11px; border-radius: 50%; flex: none; }
.hk-dot.r { background: #f26d63; }
.hk-dot.y { background: #f5bd4f; }
.hk-dot.g { background: #58c356; }
.hk-mock-url {
  flex: 1;
  min-width: 0;
  margin-left: 8px;
  padding: 6px 12px;
  border: 1px solid #e7e6f0;
  border-radius: 8px;
  background: #fff;
  color: #8181a5;
  font-size: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 머리줄 — 주소가 길어도 버튼 밑으로 파고들지 않게 */
.hk-top > div:first-child { flex: 1 1 320px; min-width: 0; }
.hk-url { flex-wrap: wrap; row-gap: 4px; }
.hk-url-pending, .hk-url a { min-width: 0; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* 접이식 요약 — 제목·배지·설명이 서로 밀지 않게 */
.hk-fold summary { gap: 12px; }
.hk-fold summary:hover { background: #fafaff; }
.hk-fold { transition: border-color .15s ease; }
.hk-fold[open], .hk-fold:hover { border-color: #d5d3e8; }
.hk-fold-tt { flex: 1; min-width: 0; display: grid; gap: 3px; }
.hk-fold-tt strong { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 14.5px; }
.hk-fold-tt small { display: block; color: #8181a5; font-size: 12.5px; line-height: 1.55; overflow-wrap: anywhere; }

/* 큰 버튼 두 개 — 같은 키에 호버 손맛 */
.hk-cta-btn { transition: transform .15s ease, box-shadow .2s ease, border-color .15s ease; }
.hk-cta-btn:hover { transform: translateY(-1px); box-shadow: 0 10px 26px rgba(13, 10, 44, .1); }
.hk-cta-btn:active { transform: none; }

/* ── 홈페이지 패널 2차 다듬기 — 목업 바 안의 작은 행동 버튼 + 폴드 저장 ── */
.hk-mock-actions { display: flex; gap: 6px; flex: none; }
.hk-mock-actions button {
  min-height: 30px;
  padding: 0 11px;
  border: 1px solid #dfe3ea;
  border-radius: 8px;
  background: #fff;
  color: #3d3a52;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}
.hk-mock-actions button:hover { border-color: #b9b6d6; }
.hk-mock-actions .hk-mock-edit { border-color: #3272db; background: #3272db; color: #fff; }
.hk-mock-actions .hk-mock-edit:hover { background: #2a63c2; }
.hk-dots { display: inline-flex; gap: 7px; flex: none; }
.hk-fold-save { margin-top: 14px; display: flex; justify-content: flex-end; }
.hk-fold-save button {
  min-height: 38px;
  padding: 0 16px;
  border: 0;
  border-radius: 9px;
  background: #3272db;
  color: #fff;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}
.hk-fold-save button:disabled { opacity: .5; cursor: default; }

/*
 * 텍스트 판 — 글자를 고르면 오른쪽에 뜨는 도킹 패널(Wix 인스펙터 식).
 * 화면 글자와 양방향으로 이어져, 내용은 여기서든 그 자리에서든 고칠 수 있다.
 */
.bw-inspector {
  position: fixed;
  top: 64px;
  right: 14px;
  z-index: 90;
  width: min(296px, calc(100vw - 28px));
  max-height: calc(100dvh - 130px);
  overflow: auto;
  display: grid;
  gap: 14px;
  padding: 14px;
  border-radius: 14px;
  background: #fff;
  border: 1px solid #e3e6ee;
  box-shadow: 0 18px 60px rgba(22, 28, 45, .22);
  animation: bwInsIn .18s ease backwards;
}
@keyframes bwInsIn { from { opacity: 0; transform: translateX(10px); } }
.bw-inspector > header { display: flex; align-items: center; justify-content: space-between; }
.bw-inspector > header strong { display: inline-flex; align-items: center; gap: 6px; font-size: 14px; color: #161c2d; }
.bw-inspector > header button { border: 0; background: transparent; color: #5d6270; cursor: pointer; padding: 4px; display: grid; place-items: center; border-radius: 8px; }
.bw-inspector > header button:hover { background: #f1f3f8; color: #161c2d; }
.bw-ins-field { display: grid; gap: 7px; }
.bw-ins-field > span { font-size: 12.5px; font-weight: 700; color: #5d6270; display: flex; justify-content: space-between; align-items: baseline; }
.bw-ins-field > span b { color: #473bf0; font-size: 12.5px; }
.bw-ins-field textarea {
  width: 100%;
  resize: vertical;
  padding: 9px 11px;
  border: 1px solid #dfe3ea;
  border-radius: 10px;
  font: inherit;
  font-size: 14px;
  line-height: 1.5;
  color: #161c2d;
}
.bw-ins-field textarea:focus { outline: 2px solid #473bf0; outline-offset: -1px; }
.bw-ins-field small { color: #8e93a4; font-size: 11.5px; }
.bw-ins-field input[type="range"] { width: 100%; accent-color: #473bf0; }
.bw-ins-steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.bw-ins-steps button {
  min-height: 30px;
  padding: 0 2px;
  border: 1px solid #dfe3ea;
  border-radius: 8px;
  background: #fff;
  font-size: 12px;
  font-weight: 700;
  color: #3d3a52;
  cursor: pointer;
  white-space: nowrap;
}
.bw-ins-steps button.on { border-color: #473bf0; background: #473bf0; color: #fff; }
.bw-ins-done {
  min-height: 38px;
  border: 0;
  border-radius: 10px;
  background: #161c2d;
  color: #fff;
  font-size: 13.5px;
  font-weight: 700;
  cursor: pointer;
}
/*
 * 전역 `button:not(.plan-ui *) svg { display:none }` 가 에디터 버튼 아이콘까지
 * 숨겼다(되돌리기·다시·닫기·휴지통이 빈 네모로 보였다) — 에디터 안에서는 되살린다.
 */
.landing-visual-builder button svg { display: inline-block !important; }

/* 메뉴 판 — 항목 줄(이름·이동·삭제)과 URL 칸 */
.bw-menu-hint { margin: 0; font-size: 12px; line-height: 1.5; color: #8e93a4; }
.bw-menu-item { display: grid; gap: 6px; }
.bw-menu-row { display: grid; grid-template-columns: 1fr auto auto; gap: 6px; }
.bw-menu-row input, .bw-menu-row select, .bw-menu-url {
  min-height: 34px;
  padding: 0 10px;
  border: 1px solid #dfe3ea;
  border-radius: 8px;
  font-size: 13px;
  background: #fff;
  color: #161c2d;
  min-width: 0;
}
.bw-menu-row select { padding-right: 26px; }
.bw-menu-row > button { border: 1px solid #dfe3ea; border-radius: 8px; background: #fff; color: #8e93a4; cursor: pointer; padding: 0 9px; display: grid; place-items: center; }
.bw-menu-row > button:disabled { opacity: .35; cursor: default; }
.bw-menu-row > button:hover:not(:disabled) { color: #d64545; border-color: #eab8b8; }
.bw-menu-add {
  min-height: 34px;
  border: 1px dashed #c9cede;
  border-radius: 8px;
  background: #fff;
  color: #473bf0;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.bw-menu-panel .bw-btn-actions button:disabled { opacity: .5; cursor: default; }

/* 선택 툴바 — 누른 요소 바로 위에 뜨는 액션 줄(Wix 식) */
.bw-eltool {
  position: fixed;
  transform: translate(-50%, calc(-100% - 10px));
  z-index: 95;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 6px;
  border-radius: 999px;
  background: #161c2d;
  box-shadow: 0 10px 30px rgba(22, 28, 45, .35);
  animation: bwInsIn .12s ease backwards;
}
.bw-eltool-kind { padding: 0 8px 0 6px; font-size: 12px; font-weight: 800; color: #8f96ab; }
.bw-eltool button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 28px;
  padding: 0 11px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: #e8ebf4;
  font-size: 12.5px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
}
.bw-eltool button:hover { background: #2a3147; }
.bw-eltool button.danger { color: #ff9d9d; }
.bw-eltool button.danger:hover { background: #3a2530; }
.bw-eltool button svg { display: inline-block !important; }

/* 숨긴 섹션의 빈 자리 — 캔버스 위 '되살리기' 줄(편집기 전용) */
.bw-restore-strip {
  position: absolute;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 40;
  border: 1px dashed #473bf0;
  border-radius: 999px;
  background: #ffffffef;
  color: #473bf0;
  font-size: 22px;
  font-weight: 700;
  padding: 10px 26px;
  cursor: pointer;
  white-space: nowrap;
  box-shadow: 0 6px 24px rgba(22, 28, 45, .16);
}
.bw-restore-strip:hover { background: #473bf0; color: #fff; }

/* 섹션 순서 판 */
.bw-sec-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.bw-sec-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid #e8eaf1;
  border-radius: 10px;
  font-size: 12.5px;
  font-weight: 600;
  color: #3d3a52;
  background: #fff;
  cursor: grab;
}
.bw-sec-list li.locked { cursor: default; background: #f7f8fb; color: #8e93a4; }
.bw-sec-list li.locked em { font-style: normal; font-size: 11px; font-weight: 700; color: #b0b5c4; border: 1px solid #e0e3ec; border-radius: 6px; padding: 1px 6px; }
.bw-sec-list li > span:first-of-type { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bw-sec-list li svg { color: #b0b5c4; flex: none; }
.bw-sec-arrows { display: inline-flex; gap: 4px; }
.bw-sec-arrows button {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border: 1px solid #dfe3ea;
  border-radius: 8px;
  background: #fff;
  color: #3d3a52;
  cursor: pointer;
}
.bw-sec-arrows button:disabled { opacity: .3; cursor: default; }
.bw-sec-arrows button:hover:not(:disabled) { border-color: #473bf0; color: #473bf0; }

/* 우클릭 메뉴 — Wix 식 컨텍스트 메뉴 */
.bw-ctx {
  position: fixed;
  z-index: 120;
  min-width: 176px;
  padding: 6px;
  border-radius: 12px;
  background: #fff;
  border: 1px solid #e3e6ee;
  box-shadow: 0 14px 44px rgba(22, 28, 45, .24);
  display: grid;
  animation: bwInsIn .12s ease backwards;
}
.bw-ctx button {
  text-align: left;
  border: 0;
  background: transparent;
  padding: 9px 11px;
  border-radius: 8px;
  font-size: 13.5px;
  font-weight: 600;
  color: #161c2d;
  cursor: pointer;
}
.bw-ctx button:hover { background: #f1f3f8; }
.bw-ctx button.danger { color: #c73a3a; }
.bw-ctx button.danger:hover { background: #fbeeee; }

/* 숨긴 자리 — 위쪽 배지 버튼과 복원 목록 */
.bw-editor-hiddenbtn { display: inline-flex; align-items: center; gap: 5px; font-weight: 700; }
.bw-editor-hiddenbtn.on { background: #161c2d; color: #fff; }
.bw-editor-hiddenbtn.on svg { stroke: #fff; }
.bw-hidden-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.bw-hidden-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid #e8eaf1;
  border-radius: 10px;
  font-size: 12.5px;
  color: #3d3a52;
}
.bw-hidden-list li span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bw-hidden-list li button {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 1px solid #dfe3ea;
  border-radius: 999px;
  background: #fff;
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 700;
  color: #473bf0;
  cursor: pointer;
}
.bw-hidden-list li button:hover { border-color: #473bf0; }
/* 폰에서는 아래 시트로 — 오른쪽에 둘 자리가 없다 */
@media (max-width: 640px) {
  .bw-inspector { top: auto; right: 10px; left: 10px; bottom: 10px; width: auto; max-height: 46dvh; }
  @keyframes bwInsIn { from { opacity: 0; transform: translateY(12px); } }
}

/* ── 어드민 홈페이지 편집 ──────────────────────────────────
   실제 홈을 iframe 으로 띄우고 그 위에서 섹션을 고른다.
   껍데기(.sc-*)는 iframe 안(홈 페이지)에서, 나머지는 어드민 화면에서 쓴다. */

/* 홈 안쪽 — 섹션 테두리와 고르기 줄 */
.sc-chrome { position: absolute; inset: 0; pointer-events: none; z-index: 900; }
.sc-box {
  position: absolute;
  border: 2px dashed rgba(50, 114, 219, .45);
  border-radius: 8px;
  pointer-events: none;
  transition: border-color .15s ease, background .15s ease;
}
.sc-box:hover, .sc-box.on { border-color: #3272db; background: rgba(50, 114, 219, .06); }
.sc-box.off { border-color: #d38b8b; background: rgba(211, 69, 69, .07); }
.sc-box-bar {
  position: absolute;
  top: 8px;
  right: 8px;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border-radius: 999px;
  background: #161c2d;
  box-shadow: 0 8px 24px rgba(22, 28, 45, .3);
  pointer-events: auto;
}
.sc-box-name { max-width: 190px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 0 8px; border: 0; background: transparent; color: #98a0b6; font-size: 12px; font-weight: 800; cursor: pointer; }
.sc-box-bar button {
  min-height: 26px;
  padding: 0 10px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: #e8ebf4;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
}
.sc-box-bar button:hover { background: #2a3147; }
.sc-box-bar button.danger { color: #ff9d9d; }
.sc-box-bar button.danger:hover { background: #3a2530; }
.sc-box-bar button.restore { color: #8ee0a6; }
.sc-box-bar button.restore:hover { background: #23392c; }
.sc-box-fixed { padding: 0 9px; font-size: 11.5px; font-weight: 700; color: #6f7896; }
.sc-box-off-tag {
  position: absolute;
  top: 8px;
  left: 8px;
  padding: 4px 10px;
  border-radius: 999px;
  background: #c73a3a;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  pointer-events: none;
}
/* 숨긴 섹션은 흐리게 — 편집기에서만 보인다(손님 화면에서는 아예 안 그린다) */
.sc-editing [data-sc-section] { transition: opacity .15s ease; }

/* 어드민 화면 — 좌 미리보기 / 우 편집 */
.admin-home-editor { display: flex; flex-direction: column; height: 100dvh; background: #f4f6fa; }
.admin-home-editor > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 20px;
  background: #fff;
  border-bottom: 1px solid #e3e6ee;
  flex: none;
}
.admin-home-editor > header > div { display: flex; align-items: center; gap: 12px; }
.admin-home-editor > header img { width: 30px; height: 30px; border-radius: 8px; }
.admin-home-editor > header span { display: grid; }
.admin-home-editor > header strong { font-size: 15px; color: #161c2d; }
.admin-home-editor > header small { font-size: 12px; color: #7b8194; }
.admin-home-editor > header nav { display: flex; gap: 6px; flex-wrap: wrap; }
.admin-home-editor > header nav a { padding: 7px 12px; border-radius: 999px; font-size: 13px; font-weight: 700; color: #5d6270; }
.admin-home-editor > header nav a.active { background: #161c2d; color: #fff; }

.admin-home-body { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 14px; padding: 14px; }
.admin-home-preview { min-width: 0; display: flex; flex-direction: column; border-radius: 14px; overflow: hidden; background: #fff; border: 1px solid #e3e6ee; }
.admin-home-mock { display: flex; align-items: center; gap: 10px; padding: 9px 12px; background: #f7f8fb; border-bottom: 1px solid #e8eaf1; flex: none; }
.admin-home-dots { display: inline-flex; gap: 5px; }
.admin-home-dots i { width: 9px; height: 9px; border-radius: 50%; background: #d6dae4; }
.admin-home-url { flex: 1; font-size: 12.5px; color: #7b8194; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.admin-home-mock a { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 700; color: #3272db; }
.admin-home-preview iframe { flex: 1; width: 100%; border: 0; background: #fff; }

.admin-home-side { min-width: 0; display: flex; flex-direction: column; gap: 12px; overflow: auto; }
.admin-home-seclist { display: grid; gap: 5px; padding: 10px; border-radius: 14px; background: #fff; border: 1px solid #e3e6ee; flex: none; }
.admin-home-seclist button {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  font-size: 13px;
  font-weight: 600;
  color: #3d3a52;
  text-align: left;
  cursor: pointer;
}
/* 전역 `button:not(.plan-ui *) svg { display:none }` 이 어드민 아이콘도 지운다 — 여기선 되살린다 */
.admin-home-editor button svg, .sc-box-bar button svg { display: inline-block !important; }
.admin-home-seclist button svg { color: #b0b5c4; flex: none; }
.admin-home-seclist button:hover { background: #f4f6fa; }
.admin-home-seclist button.on { border-color: #3272db; background: #eef4fd; color: #1f4f9e; }
.admin-home-seclist button.off { color: #b0b5c4; text-decoration: line-through; }

.admin-home-fields { display: grid; gap: 12px; padding: 14px; border-radius: 14px; background: #fff; border: 1px solid #e3e6ee; }
.admin-home-fields > header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.admin-home-fields h2 { margin: 0; font-size: 15px; color: #161c2d; }
.admin-home-fields > header em { font-style: normal; font-size: 11.5px; font-weight: 700; color: #b0b5c4; border: 1px solid #e0e3ec; border-radius: 6px; padding: 2px 7px; }
.admin-home-fields > header button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 30px;
  padding: 0 11px;
  border: 1px solid #e6c9c9;
  border-radius: 999px;
  background: #fff;
  font-size: 12.5px;
  font-weight: 700;
  color: #c73a3a;
  cursor: pointer;
}
.admin-home-fields > header button.restore { border-color: #bfe3c9; color: #2f7d4a; }
.admin-home-fields label { display: grid; gap: 5px; font-size: 12.5px; font-weight: 700; color: #5d6270; }
.admin-home-fields input, .admin-home-fields textarea {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid #dfe3ea;
  border-radius: 10px;
  font: inherit;
  font-size: 13.5px;
  line-height: 1.5;
  color: #161c2d;
  background: #fff;
  resize: vertical;
}
.admin-home-fields input:focus, .admin-home-fields textarea:focus { outline: 2px solid #3272db; outline-offset: -1px; }
.admin-home-fields label small { font-weight: 400; color: #8e93a4; font-size: 11.5px; }
.admin-home-offnote { margin: 0; padding: 8px 11px; border-radius: 9px; background: #fbeeee; color: #c73a3a; font-size: 12.5px; font-weight: 700; }
.admin-home-hint { margin: 0; color: #8e93a4; font-size: 12px; line-height: 1.5; }

.admin-home-actions { position: sticky; bottom: 0; display: grid; gap: 8px; padding: 12px; border-radius: 14px; background: #fff; border: 1px solid #e3e6ee; }
.admin-home-actions p { margin: 0; font-size: 12.5px; color: #2f7d4a; }
.admin-home-actions > div { display: flex; justify-content: flex-end; gap: 8px; }
.admin-home-actions button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 38px;
  padding: 0 16px;
  border: 1px solid #dfe3ea;
  border-radius: 10px;
  background: #fff;
  font-size: 13.5px;
  font-weight: 700;
  color: #3d3a52;
  cursor: pointer;
}
.admin-home-actions button.save { border-color: #3272db; background: #3272db; color: #fff; }
.admin-home-actions button:disabled { opacity: .5; cursor: default; }
.admin-home-actions button svg { display: inline-block !important; }

@media (max-width: 1000px) {
  .admin-home-editor { height: auto; }
  .admin-home-body { grid-template-columns: 1fr; }
  .admin-home-preview { height: 62dvh; }
}

/* 글 한 조각 — 고른 섹션 안에서만 보이는 작은 테두리와 줄 */
.sc-field {
  position: absolute;
  border: 1px dashed rgba(199, 58, 58, .5);
  border-radius: 6px;
  pointer-events: none;
}
.sc-field.off { background: rgba(199, 58, 58, .1); }
.sc-field-bar {
  position: absolute;
  bottom: 100%;
  left: 0;
  transform: translateY(-4px);
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 3px;
  border-radius: 999px;
  background: #4a2230;
  box-shadow: 0 6px 18px rgba(22, 28, 45, .28);
  pointer-events: auto;
  white-space: nowrap;
}
.sc-field-bar > span { padding: 0 8px; font-size: 11.5px; font-weight: 800; color: #e3b3bd; }
.sc-field-bar button {
  min-height: 24px;
  padding: 0 9px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: #ffe3e6;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
}
.sc-field-bar button:hover { background: #62303f; }
.sc-field-bar button.danger { color: #ffb0b0; }
.sc-field-bar button.restore { color: #a7e6b8; }

/* 어드민 — 글 조각 삭제 표시 */
.admin-home-fields label > span { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.admin-home-fields label > span button {
  border: 0;
  background: transparent;
  font-size: 11.5px;
  font-weight: 700;
  color: #c73a3a;
  cursor: pointer;
  padding: 2px 4px;
  border-radius: 6px;
}
.admin-home-fields label > span button:hover { background: #fbeeee; }
.admin-home-fields label > span button.restore { color: #2f7d4a; }
.admin-home-fields label > span button.restore:hover { background: #eef7f1; }
.admin-home-fields label.off > span { color: #b0b5c4; }
.admin-home-fields label.off input, .admin-home-fields label.off textarea { background: #f4f6fa; color: #b0b5c4; text-decoration: line-through; }
